    List<String> parts = id.split('_');
    int r = int.parse(parts[1]);
    int c = int.parse(parts[2]);

    List<List<int>> deltas = [
      [-1, 0], [1, 0], [0, -1], [0, 1]
    ];

    for (List<int> delta in deltas) {
      int nr = r + delta[0];
      int nc = c + delta[1];
      String neighborId = 'P_$nr,$_nc';

      if (nr >= 0 && nr < grid.length &&
