List<int> dbscan(List<List<double>> data, double eps, int minPts) {
  int n = data.length;
  if (n == 0) return <int>[];

  List<int> labels = List.filled(n, 0); 
  int clusterId = 0;

  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) continue; 

    List<int> neighbors = regionQuery(data, i, eps);

    if (neighbors.length < minPts) {
      labels[i] = -1; 
      continue;
    }

    clusterId++;
    labels[i] = clusterId;

    expandCluster(data, labels, i, neighbors, clusterId, eps, minPts);
  }
  return labels;
}

void expandCluster(
  List<List<double>> data,
  List<int> labels,
  int pointIdx,
  List<int> neighbors,
  int clusterId,
  double eps,
  int minPts,
) {
  labels[pointIdx] = clusterId;
  int regionIdx = 0;
  while (regionIdx < neighbors.length) {
    int currentIdx = neighbors[regionIdx];

    if (labels[currentIdx] == -1) {

      labels[currentIdx] = clusterId;
