List<int> dbscan(List<List<double>> data, int k, double eps, int minPts) {
  int n = data.length;
  List<int> labels = List.filled(n, 0); 
  int clusterId = 0;

  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) continue; 
    List<int> neighbors = regionQuery(data, i, eps);
    if (neighbors.length < minPts) {
      labels[i] = -1; 
    } else {
      clusterId++;
      expandCluster(data, labels, i, neighbors, clusterId, k, eps, minPts);
    }
  }
  return labels;
}

void expandCluster(List<List<double>> data, List<int> labels, int pointIdx, List<int> neighbors, int clusterId, int k, double eps, int minPts) {
  labels[pointIdx] = clusterId;

  List<int> seeds = List.from(neighbors);
  for (int i = 0; i < seeds.length; i++) {
    int p = seeds[i];
    if (labels[p] == -1) {
      labels[p] = clusterId;
    }
    if (labels[p] == 0) {
      labels[p] = clusterId;
      List<int> newNeighbors = regionQuery(data, p, eps);
      if (newNeighbors.length >= minPts) {
        for (int j = 0; j < newNeighbors.length; j++) {
          int neighbor = newNeighbors[j];
          if (!seeds.contains(neighbor)) seeds.add(neighbor);
        }
      }
    }
  }
}

