Map<String, int> fn0(List<int> requests, int maxDistance) {
  int n = requests.length;
  if (n == 0) return {'idle': 0, 'serve': 0, 'travel': 0};
  List<int> serve = List<int>.filled(n, 0);
  List<int> travel = List<int>.filled(n, 0);
  for (int i = 1; i < n; i++) {
    int d = (requests[i] - requests[i - 1]).abs();
    travel[i] = travel[i - 1] + d;
  }
  int best = travel[n - 1];
  int lo = 0, hi = n;
  while (lo < hi) {
    int mid = (lo + hi + 1) ~/ 2;
    int t = travel[mid];
    if (t <= best + maxDistance) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  int first = lo;
  int last = n - 1;
  while (first < last) {
    int mid = (first + last) ~/ 2;
    if (travel[mid] <= best + maxDistance) {
      first = mid + 1;
    } else {
      last = mid;
    }
  }
  serve[n - 1] = 1;
  int sum = 0;
  for (int i = first; i < n; i++) {
    if (travel[i] <= best + maxDistance) {
      serve[i] = 1;
      sum++;
    }
  }
  return {'idle': n - sum, 'serve': sum, 'travel': best};
}

