Set<int> fn0(String signalPattern) {
  final result = <int>{};
  if (signalPattern.isEmpty) return result;
  final segments = signalPattern.split(',');
  final required = segments[0].split('|');
  final optional = segments.length > 1 ? segments[1].split('|') : <String>[];
  final total = required.length + optional.length;
  if (total == 0) return result;
  final bits = List<int>.generate(total, (i) => i < required.length ? 1 : 0);
  final bitsSet = <Set<int>>[];
  for (final segment in segments) {
    final options = segment.split('|');
    bitsSet.add(<int>{for (final o in options) int.parse(o)});
  }
  const maxMasks = 16;
  final queue = <List<int>>[[...bits]];
  while (queue.isNotEmpty) {
    final current = queue.removeAt(0);
    final mask = current.where((b) => b == 1).fold(0, (sum, b) => sum + b);
    if (mask == maxMasks) {
      result.add(mask);
      continue;
    }
    for (var i = 0; i < bitsSet.length; i++) {
      if (current[i] == 1) continue;
      for (final bit in bitsSet[i]) {
        final next = List<int>.from(current);
        next[i] = bit;
        queue.add(next);
      }
    }
  }
  return result;
}

