List<String> fn0(List<String> entries) {
  Map<String, int> balances = {};
  List<String> deposits = [];
  List<String> withdrawals = [];
  List<String> transfers = [];
  Set<String> seenAccounts = {};

  for (String entry in entries) {
    List<String> parts = entry.split(':');
    String type = parts[0];
    String value = parts[1];
    String account = parts[2];

    if (value.contains('.')) {
      String integerPart = value.split('.')[0];
      if (integerPart.isNotEmpty) {
        int numericValue = int.parse(integerPart);
        if (type == 'D') {
          balances[account] = (balances[account] ?? 0) + numericValue;
        } else if (type == 'W') {
          balances[account] = (balances[account] ?? 0) - numericValue;
        } else if (type == 'T') {
          List<String> toParts = value.split('|');
          String to = toParts[0];
          int amount = int.parse(toParts[1]);
          balances[account] = (balances[account] ?? 0) - amount;
          balances[to] = (balances[to] ?? 0) + amount;
        }
      }
    } else {
      int numericValue = int.parse(value);
      if (type == 'D') {
        deposits.add(account);
      } else if (type == 'W') {
        withdrawals.add(account);
      } else if (type == 'T') {
        transfers.add(account);
      }
    }

    if (account.isNotEmpty && !seenAccounts.contains(account)) {
      seenAccounts.add(account);
    }
  }

  List<String> result = [];
  for (String account in seenAccounts) {
    int balance = balances[account] ?? 0;
    result.add('$account:$balance');
  }
  result.sort();
  return result;
}

