String fn0(List<int> startTimes, List<int> endTimes, int maxGap) {
  if (startTimes.isEmpty || startTimes.length != endTimes.length) {
    return 'invalid:empty';
  }
  int n = startTimes.length;
  for (int i = 0; i < n; i++) {
    if (endTimes[i] <= startTimes[i]) {
      return 'invalid:order';
    }
  }
  List<int> events = [];
  for (int i = 0; i < n; i++) {
    events.add(startTimes[i]);
    events.add(endTimes[i]);
  }
  events.sort();
  List<int> durations = [];
  int prev = events[0];
  int count = 1;
  for (int i = 1; i < events.length; i++) {
    if (events[i] == prev) {
      count++;
    } else {
      durations.add(count);
      prev = events[i];
      count = 1;
    }
  }
  durations.add(count);
  int totalOverlap = 0;
  for (int d in durations) {
    totalOverlap += d * (d + 1) ~/ 2;
  }
  if (totalOverlap == 0) {
    return 'gap:$maxGap';
  }
  int bestGap = maxGap;
  int bestStart = -1;
  int bestEnd = -1;
  for (int s = 0; s < n; s++) {
    int curStart = startTimes[s];
    int curEnd = endTimes[s];
    int overlap = 0;
    for (int d in durations) {
      if (curStart < prev || curEnd > prev) {
        overlap += d;
      }
    }
    int score = overlap + (curStart < bestStart ? 1 : 0) + (curEnd > bestEnd ? 1 : 0);
    if (score < totalOverlap && (curEnd - curStart) < bestGap) {
      bestGap = curEnd - curStart;
      bestStart = curStart;
      bestEnd = curEnd;
    }
  }
  if (bestGap == maxGap) {
    return 'gap:$bestGap';
  }
  return '$bestStart:$bestEnd:$bestGap';
}

