void fn0() {

  final List<int> arr = [4, 2, 2, 8, 3, 3, 1, 7];

  final int n = arr.length;
  if (n == 0) {
    print('The array is empty. Cannot find the k-th smallest element.');
    return;
  }

  final int k = 5; 
  if (k <= 0 || k > n) {
    print('Invalid k! Must be between 1 and $n.');
    return;
  }

  print('Original array: $arr');
  print('Finding the $k-th smallest element...');

  int partition(List<int> a, int low, int high) {
    final int pivot = a[high];
    int i = low;

    for (int j = low; j < high; j++) {
      if (a[j] <= pivot) {
        final int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        i++;
      }
    }

    final int tmp = a[i];
    a[i] = a[high];
    a[high] = tmp;
    return i;
  }

  int quickSelect(List<int> a, int low, int high, int k) {
    int pivotIndex;

    do {
      pivotIndex = partition(a, low, high);

      if (pivotIndex == k) {
        return a[pivotIndex];
      } else if (pivotIndex < k) {
        low = pivotIndex + 1;
      } else {
        high = pivotIndex - 1;
      }
    } while (true);
  }

  int kthSmallest = quickSelect(arr, 0, n - 1, k - 1);

  print('The $k-th smallest element is: $kthSmallest');

  print('Verification:');
  final List<int> sorted = List.from(arr);
  sorted.sort();
  print('Sorted array: $sorted');
  print('The $k-th smallest element is indeed: ${sorted[k - 1]}');
}

