import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int populationSize = 30;
  const int chromosomeLength = 16;
  const double crossoverRate = 0.7;
  const double mutationRate = 0.01;
  const int maxGenerations = 100;
  const int target = 30;


  final Random rand = Random(0);
  final List<List<int>> population = List.generate(
    populationSize,
    (_) => List.generate(chromosomeLength, (_) => rand.nextBool() ? 1 : 0),
  );

  int fitness(List<int> chrom) => chrom.fold(0, (sum, bit) => sum + bit);

  List<int> bestChrom = population[0];
  int bestFit = fitness(bestChrom);

  int generation = 0;

  while (generation < maxGenerations) {

    population.sort((a, b) => fitness(b).compareTo(fitness(a)));

    final List<List<int>> newPopulation = [];

    newPopulation.add(population[0]); 

    if (population[0].join() == population[1].join()) {
      newPopulation.add(population[0]);
    } else {
      newPopulation.add(population[1]);
    }

    while (newPopulation.length < populationSize) {
      List<int>? parent1;
      List<int>? parent2;

      if (rand.nextDouble() < crossoverRate) {

        int a = rand.nextInt(populationSize - 1) + 1;
        int b = rand.nextInt(populationSize - 1) + 1;
        if (a > b) { final t = a; a = b; b = t; }
        parent1 = population[a];
        parent2 = population[b];
      } else {

        parent1 = population[rand.nextInt(populationSize)];
        parent2 = population[rand.nextInt(populationSize)];
      }

      final int crossoverPoint = rand.nextInt(chromosomeLength);
      final List<int> child1 = [
        for (int i = 0; i < crossoverPoint; i++) parent1![i],
        for (int i = crossoverPoint; i < chromosomeLength; i++) parent2![i],
      ];
      final List<int> child2 = [
        for (int i = 0; i < crossoverPoint; i++) parent2![i],
        for (int i = crossoverPoint; i < chromosomeLength; i++) parent1![i],
      ];

      for (var child in [child1, child2]) {
        for (int i = 0; i < chromosomeLength; i++) {
          if (rand.nextDouble() < mutationRate) {
            child[i] = 1 - child[i];
          }
        }
        newPopulation.add(child);
      }
    }
    population = newPopulation;
    generation++;

    final int currentBestFit = fitness(population[0]);
    if (currentBestFit > bestFit) {
      bestFit = currentBestFit;
      bestChrom = population[0];
      if (bestFit == target) {
        print('Target reached in generation $generation!');
        break;
      }
    }
    if (generation % 10 == 0) {
      print('Generation $generation: Best fitness = $bestFit, Chromosome = ${bestChrom.join()}');
