double fn0(int rows, int cols, List<List<int>> moistureGrid, int startRow, int startCol, int targetMoisture) {
  if (rows <= 0 || cols <= 0 || startRow < 0 || startRow >= rows || startCol < 0 || startCol >= cols) {
    return -1.0;
  }

  final List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  final List<List<int>> queue = [[startRow, startCol]];
  visited[startRow][startCol] = true;
  int depth = 0;
  int nodesAtCurrentDepth = 1;
  int moistureSum = 0;

  while (queue.isNotEmpty) {
    final current = queue.removeAt(0);
    final r = current[0];
    final c = current[1];

    moistureSum += moistureGrid[r][c];

    if (moistureGrid[r][c] == targetMoisture) {
      return moistureSum / (depth + 1);
    }

    final List<List<int>> directions = [
      [-1, 0],
      [1, 0],
      [0, -1],
      [0, 1]
    ];

    for (final dir in directions) {
      final nr = r + dir[0];
      final nc = c + dir[1];

      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
        visited[nr][nc] = true;
        queue.add([nr, nc]);
      }
    }

    nodesAtCurrentDepth--;
    if (nodesAtCurrentDepth == 0) {
      depth++;
      nodesAtCurrentDepth = queue.length;
    }
  }

  return -1.0;
}

