Set<int> fn0(List<int> signalLevels, int maxGap, int minRunLength, int maxRunLength) {
  Set<int> result = {};
  int n = signalLevels.length;
  if (n < minRunLength || minRunLength <= 0 || maxRunLength < minRunLength) {
    return result;
  }

  for (int start = 0; start <= n - minRunLength; start++) {
    bool valid = true;
    for (int i = start + 1; i < start + minRunLength; i++) {
      if (signalLevels[i] < signalLevels[i - 1]) {
        valid = false;
        break;
      }
    }
    if (!valid) continue;

    for (int end = start + minRunLength; end <= n && end <= start + maxRunLength; end++) {
      bool increasing = true;
      for (int i = end; i > start + minRunLength; i--) {
        if (signalLevels[i] < signalLevels[i - 1]) {
          increasing = false;
          break;
        }
      }
      if (!increasing) continue;

      int minVal = signalLevels[start];
      int maxVal = signalLevels[start];
      for (int i = start + 1; i < end; i++) {
        if (signalLevels[i] < minVal) minVal = signalLevels[i];
        if (signalLevels[i] > maxVal) maxVal = signalLevels[i];
      }
      if (maxVal - minVal > maxGap) continue;

      result.add(start);
      break;
    }
  }

  return result;
}

