int dfs(List<List<int>> grid, List<List<bool>> visited, int r, int c) {
  if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == 0 || visited[r][c]) {
    return 0;
  }

  visited[r][c] = true;
  int area = 1;

  List<List<int>> directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  for (var dir in directions) {
    int nr = r + dir[0];
    int nc = c + dir[1];
    area += dfs(grid, visited, nr, nc);
  }

  return area;
}

