void fn0() {
  const int n = 8;
  List<int> queens = List.filled(n, -1);

  bool isSafe(int row, int col) {
    for (int i = 0; i < row; i++) {
      int qCol = queens[i];
      if (qCol == col || 
          (i - row).abs() == (qCol - col).abs()) {
        return false;
      }
    }
    return true;
  }

  int count = 0;
  void solve(int row) {
    if (row == n) {
      count++;
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        queens[row] = col;
        solve(row + 1);
      }
    }
  }

  solve(0);
  print('Total N-Queens solutions for $n: $count');
}

