  addEdge(1, 3, 15);
  addEdge(2, 3, 11);
  addEdge(2, 5, 2);
  addEdge(3, 5, 9);
  addEdge(4, 0, 10);
  addEdge(4, 2, 1);
  addEdge(5, 4, 6);

  List<List<int>> dist = List.generate(n, (_) => List.filled(n, INF));
  List<List<int>> cnt = List.generate(n, (_) => List.filled(n, 0));
  List<List<int>> pred = List.generate(n, (_) => List.filled(n, -1));

  for (int i = 0; i < n; i++) {
    dist[i][i] = 0;
    cnt[i][i] = 1;
    pred[i][i] = -1;
  }

