    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {

        if (dist[i][k] > INF || dist[k][j] > INF) continue;

        int cost = dist[i][k] + dist[k][j];

        if (cost < dist[i][j]) {
          dist[i][j] = cost;
          pred[i][j] = pred[i][k];
          cnt[i][j] = cnt[i][k];
        } else if (cost == dist[i][j]) {
          if (pred[i][k] != -1 && pred[i][k] != pred[i][j]) {
            cnt[i][j]++;
            if (pred[i][k] < pred[i][j]) {
              pred[i][j] = pred[i][k];
            }
          }
        }
      }
    }
  }

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (dist[i][j] == INF) {
        dist[i][j] = -1;
      }
    }
  }

  print('All-pairs shortest paths:');
  for (int i = 0; i < n; i++) {
    String row = '';
    for (int j = 0; j < n; j++) {
      if (dist[i][j] == -1) {
