@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<double>> transactions = [
    [1, 2, 3],
    [1, 2, 4],
    [1, 3, 4],
    [2, 3, 4],
    [1, 2],
    [1, 3],
    [2, 3],
    [1, 4],
    [1, 2, 3, 4],
  ];

  double minSupport = 0.3;
  double minConfidence = 0.7;

  Map<int, Set<int>> itemsets = {};
  Set<int> frequentItems = {};

  for (var transaction in transactions) {
    for (var item in transaction) {
      itemsets[item] = (itemsets[item] ?? {Set<int>.empty()});
      itemsets[item]!.add(Set<int>.from({item}));
      frequentItems.add(item);
    }
  }

  double minSupportCount = minSupport * transactions.length;
  Map<Set<int>, int> frequentItemsets = {};
  for (var items in itemsets.keys) {
    int count = itemsets[items]!.length;
    if (count >= minSupportCount) {
      frequentItemsets[items] = count;
    }
  }

  Map<int, int> itemFrequency = {};
  for (var itemset in frequentItemsets.keys) {
    for (var item in itemset) {
      itemFrequency[item] = (itemFrequency[item] ?? 0) + 1;
    }
  }

  Map<Set<int>, double> associationRules = {};
  for (var itemset in frequentItemsets.keys) {
    if (itemset.length == 1) continue;
    for (var antecedent in itemFrequency.keys) {
      if (!itemset.contains(antecedent)) continue;
      Set<int> consequent = {};
      for (var item in itemset) {
        if (!antecedent.contains(item)) {
          consequent.add(item);
        }
      }
      int antecedentSupport = itemFrequency[antecedent]!;
      int ruleSupport = frequentItemsets[itemset]!;
      double confidence = ruleSupport / antecedentSupport;
      if (confidence >= minConfidence) {
        associationRules[Set<int>.from(itemset)] = confidence;
      }
    }
  }

  print('Frequent Itemsets (Support ≥ $minSupport):');
  for (var itemset in frequentItemsets.keys) {
    double support = frequentItemsets[itemset]! / transactions.length;
    print('  $itemset: support = ${support.toStringAsFixed(2)}');
  }

  print('\nHigh-Confidence Association Rules (Confidence ≥ $minConfidence):');
  for (var entry in associationRules.entries) {
    var itemset = entry.key;
    double confidence = entry.value;
    Set<int> antecedent = {};
    Set<int> consequent = {};
    for (var item in itemset) {
      if (itemFrequency[item]! < itemFrequency.values.reduce((a, b) => a < b ? a : b)) {
        antecedent.add(item);
      } else {
        consequent.add(item);
      }
    }
    print('  ${antecedent.toList()} → ${consequent.toList()} (confidence: ${confidence.toStringAsFixed(2)})');
  }
}

