      int atSum = runs['A']! + runs['T']!;
      int gcSum = runs['G']! + runs['C']!;
      int gcdValue = _gcd(atSum, gcSum);

      result.add(gcdValue);
    }
  }

  return result;
}

int _gcd(int a, int b) {
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

