String fn0(List<String> events) {
  if (events.isEmpty) return "IDLE:0";
  List<List<int>> history = [];
  List<String> stack = [];
  for (String event in events) {
    if (event == "UNDO") {
      if (stack.isNotEmpty) stack.removeLast();
      if (stack.isEmpty) history.add([0, 0]);
      continue;
    }
    List<String> parts = event.split(':');
    int dir = parts[0] == 'UP' ? 1 : parts[0] == 'DOWN' ? -1 : 0;
    int amt = int.parse(parts[1]);
    int prev = stack.isEmpty ? 0 : stack.last;
    int cur = prev + dir * amt;
    stack.add(cur);
    if (stack.length > 1) {
      int last = stack[stack.length - 2];
      if (cur == last) {
        history.add([last, 0]);
        while (stack.length > 1) stack.removeLast();
      }
    } else {
      history.add([cur, 0]);
    }
  }
  int total = 0;
  for (List<int> seg in history) {
    total += seg[1];
  }
  return "IDLE:$total";
}

