List<String> fn0(String word, int editDistance) {
  List<String> edits = [];
  if (word.isEmpty) return edits;

  void generate(int index, String current) {
    if (current.length > word.length) return;
    if (current.length == word.length) {
      if (editDistance >= 0 && edits.length < editDistance) {
        edits.add(current);
      } else if (edits.length == editDistance) {
        return;
      }
    } else {
      generate(index + 1, current);
      for (int i = 0; i <= word.length - current.length; i++) {
        String prefix = word.substring(0, i);
        String suffix = word.substring(i + current.length);
        String next = prefix + word[index] + suffix;
        generate(next, current + word[index]);
      }
    }
  }

  generate(0, '');
  return edits;
}

