void fn0(List<String> args) {

  final int rows = args.isNotEmpty ? int.tryParse(args[0]) ?? 10 : 10;
  final int cols = args.length >= 2 ? int.tryParse(args[1]) ?? 10 : 10;
  final String start = args.length >= 3 ? args[2] : '0,0';
  final String end = args.length >= 4 ? args[3] : '0,0';

  int startRow = 0;
  int startCol = 0;
  int endRow = 0;
  int endCol = 0;

  if (start != '0,0') {
    final parts = start.split(',');
    startRow = int.tryParse(parts[0]) ?? 0;
    startCol = int.tryParse(parts[1]) ?? 0;
  }
  if (end != '0,0') {
    final parts = end.split(',');
    endRow = int.tryParse(parts[0]) ?? 0;
    endCol = int.tryParse(parts[1]) ?? 0;
  }

  final visited = List.generate(rows, (r) => List.filled(cols, false));
  final queue = <List<int>>[];
  queue.add([startRow, startCol, 0]);
  visited[startRow][startCol] = true;

  final List<int> path = [];
  bool found = false;

  while (queue.isNotEmpty) {
    final current = queue.removeAt(0);
    final row = current[0];
    final col = current[1];
    final steps = current[2];

    path.add(row * cols + col);

    if (row == endRow && col == endCol) {
      found = true;
      break;
    }


    if (row > 0) {
      if (!visited[row - 1][col]) {
        queue.add([row - 1, col, steps + 1]);
        visited[row - 1][col] = true;
      }
    }
    if (row < rows - 1) {
      if (!visited[row + 1][col]) {
        queue.add([row + 1, col, steps + 1]);
        visited[row + 1][col] = true;
      }
    }
    if (col > 0) {
      if (!visited[row][col - 1]) {
        queue.add([row, col - 1, steps + 1]);
        visited[row][col - 1] = true;
      }
    }
    if (col < cols - 1) {
      if (!visited[row][col + 1]) {
        queue.add([row, col + 1, steps + 1]);
        visited[row][col + 1] = true;
      }
    }
  }

  final visitedCount = visited.expand((r) => r).where((b) => b).toList().length;
  final startIdx = startRow * cols + startCol;
  final endIdx = endRow * cols + endCol;
  final pathSet = path.toSet();

  print('BFS from $start to $end in $rows x $cols grid:');
  print('Visited nodes: $visitedCount');
  print('Path length: ${path.isEmpty ? -1 : path.last - startIdx}');
  print('Found path: ${found ? 'Yes' : 'No'}');

  if (found) {
    final pathList = path.toSet().toList()..sort();
    print('Path coordinates:');
    for (final idx in pathList) {
      final r = idx ~/ cols;
      final c = idx % cols;
      print('  ($r, $c)');
    }
  } else {
    print('Path coordinates: None');
  }
}

