  }

  int rotate(int ch) {
    return (ch - 48) % 10;
  }

  List<int> digits = [];
  for (int i = 0; i < password.length; i++) {
    int code = password.codeUnitAt(i);
    if (code >= 48 && code <= 57) {
      digits.add(rotate(code));
    }
  }

  if (digits.isEmpty) {
    return 0;
  }

  int n = digits.length;
  int bestLen = 0;

  for (int m = 1; m <= n; m++) {
    for (int i = 0; i <= n - m; i++) {
      int j = i + m - 1;
      int maxR = digits[j];
      int minR = digits[j];
      bool hasDouble = false;

      for (int k = i; k <= j; k++) {
        int r = digits[k];
        if (r > maxR) {
          maxR = r;
        }
        if (r < minR) {
          minR = r;
        }
        if (k < j && digits[k] == digits[k + 1]) {
          hasDouble = true;
        }
      }

      if (maxR - minR <= maxDiff && hasDouble) {
        if (m > bestLen) {
          bestLen = m;
        }
