double fn0(List<int> cycleUnits, int startDay, int endDay) {
  if (cycleUnits.isEmpty || endDay < startDay) {
    return 0.0;
  }

  int totalDeficit = 0;
  int cycleIndex = startDay % cycleUnits.length;

  for (int day = startDay; day <= endDay; day++) {
