  int solutions = 0;

  bool isSafe(int row, int col) {
    for (int i = 0; i < row; i++) {

      final int qCol = queens[i];
      if (qCol == col) return false;

      final int diff = (row - i).abs() - (col - qCol).abs();
      if (diff == 0) return false;
    }
    return true;
  }

  void placeQueen(int row) {
    if (row == n) {

