      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        queens[row] = col;
        placeQueen(row + 1);

      }
    }
  }

  print('Solving N-Queens for n=$n');
  print('--------------------');
  placeQueen(0);
  print('--------------------');
  print('Total solutions found: $solutions');
}

