int fn0(List<List<int>> grid, int minRows, int minCols) {
  int count = 0;
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      if (grid[r][c] == 1) {
        bool valid = true;
        for (int dr = -1; dr <= 1; dr++) {
          for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) continue;
            int nr = r + dr;
            int nc = c + dc;
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[nr].length) {
              if (grid[nr][nc] == 1) {
                valid = false;
                break;
              }
            }
          }
        }
        if (valid) {
          int startRow = r;
          while (startRow >= 0 && grid[startRow][c] == 1) {
            startRow--;
          }
          int endRow = r;
          while (endRow < grid.length && grid[endRow][c] == 1) {
            endRow++;
          }
          int spanRows = endRow - startRow - 1;
          bool hasEnoughRows = spanRows >= minRows;

          startRow = c;
          while (startRow >= 0 && grid[r][startRow] == 1) {
            startRow--;
          }
          endRow = c;
          while (endRow < grid[r].length && grid[r][endRow] == 1) {
            endRow++;
          }
          int spanCols = endRow - startRow - 1;
          bool hasEnoughCols = spanCols >= minCols;

          if (hasEnoughRows && hasEnoughCols) {
            count++;
          }
        }
      }
    }
  }
  return count;
}

