  };
  int rows = grid.length;
  if (rows == 0) return ['dry:0,wet:0,mixed:0,isolated:0,surrounded:0'];
  int cols = grid[0].length;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] <= 0) {
        counts['dry'] = counts['dry']! + 1;
      } else {
        counts['wet'] = counts['wet']! + 1;
      }
    }
  }
  List<List<int>> dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int val = grid[r][c];
      if (val <= 0) continue;
      bool hasNeighbor = false;
      bool allDry = true;
      for (var d in dirs) {
        int nr = r + d[0];
        int nc = c + d[1];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
          hasNeighbor = true;
          if (grid[nr][nc] > 0) {
