          }
        }
      }
      if (!hasNeighbor) {
        counts['isolated'] = counts['isolated']! + 1;
      } else if (allDry) {
        counts['surrounded'] = counts['surrounded']! + 1;
      } else {
        counts['mixed'] = counts['mixed']! + 1;
      }
    }
  }
