        break;
      }
    }
    if (hasNegativeCycle) break;
  }

  print('Shortest distances from source $source:');
  for (int i = 0; i < n; i++) {
    if (dist[i] == INF) {
      print('Vertex $i: Unreachable (infinite distance)');
    } else {
      print('Vertex $i: Distance = ${dist[i]}');
    }
  }

  if (hasNegativeCycle) {
    print('\nGraph contains a negative-weight cycle!');
  } else {
    print('\nNo negative-weight cycle found. Results are valid.');
  }
}

