      positions.add(i);
    }
    return positions;
  }
  int n = dna.length;
  int m = motif.length;
  if (m > n) return positions;
  List<int> failure = List.filled(m, 0);
  int i = 1, j = 0;
  while (i < m) {
    if (motif[j] == motif[i]) {
      failure[i] = j + 1;
      i++;
