      i++;
    }
  }
  i = 0;
  while (i <= n - m) {
    while (i <= n - m && dna[i] != motif[0]) i++;
    if (i > n - m) break;
    j = 0;
    while (j < m) {
      if (dna[i + j] == motif[j]) {
        j++;
      } else {
        if (j > 0) {
          j = failure[j - 1];
        } else {
          break;
        }
      }
    }
    if (j == m) {
      positions.add(i);
      i += m - failure[m - 1];
    } else {
      i++;
    }
  }
  return positions;
}

