List<int> fn0(List<int> quantities, int threshold) {
  int left = 0, right = quantities.length - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (quantities[mid] < threshold) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  int firstMissing = left;
  left = 0;
  while (left < firstMissing) {
    int mid = left + (firstMissing - left) ~/ 2;
