List<String> fn0(List<int> cycleMinutes, List<int> chargeMinutes, int totalMinutes) {
  int n = cycleMinutes.length;
  if (n == 0) return [];
  if (totalMinutes < 0) return [];
  if (totalMinutes == 0) return List.filled(n, 0);
  List<String> dp = List.filled(totalMinutes + 1, '');
