      }
    }
  }
  for (int t = 1; t <= totalMinutes; t++) {
    for (int i = 0; i < n; i++) {
      if (chargeMinutes[i] > 0) {
        int prev = t - cycleMinutes[i];
        if (prev >= 0 && dp[prev] != '') {
          int currCharge = cycleMinutes[i] + chargeMinutes[i];
          String option = chargeMinutes[i] == 1 ? '1' : '$currCharge';
          if (dp[t] == '' || (dp[prev] + ',' + option).length < dp[t].length) {
            dp[t] = dp[prev] + ',' + option;
          }
        }
      }
    }
  }
  return dp[totalMinutes].split(',');
}

