@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<double>> points = [
    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  double eps = 3.0;
  int minPts = 2;

  List<int> labels = dbscan(points, eps, minPts);

  for (int i = 0; i < points.length; i++) {
    String label = labels[i] == -1 ? 'Noise' : 'Cluster ${labels[i]}';
    print('Point ${points[i]} -> $label');
  }
}

int dbscan(List<List<double>> data, double eps, int minPts) {
  int n = data.length;
  List<int> labels = List.filled(n, 0); 
  int clusterId = 0;

  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) continue; 

    List<int> region = regionQuery(data, i, eps);
    if (region.length < minPts) {
      labels[i] = -1; 
      for (int j in region) labels[j] = -1;
    } else {
      clusterId++;
      expandCluster(data, labels, i, region, clusterId, eps, minPts);
    }
  }

  return clusterId;
}

void expandCluster(
    List<List<double>> data,
    List<int> labels,
    int pointIdx,
    List<int> region,
    int clusterId,
    double eps,
    int minPts) {
  labels[pointIdx] = clusterId;
  int index = 0;
  for (int i = 0; i < region.length; i++) {
    if (labels[region[i]] == -1) {
      labels[region[i]] = clusterId;
      index++;
    }
  }
  List<int> seeds = region.sublist(0, index);
  while (seeds.isNotEmpty) {
    int current = seeds.removeLast();
    List<int> neighbors = regionQuery(data, current, eps);
    if (neighbors.length >= minPts) {
      for (int j in neighbors) {
        if (!seeds.contains(j)) seeds.add(j);
      }
    } else {
      labels[current] = -1;
    }
  }
}

List<int> regionQuery(List<List<double>> data, int idx, double eps) {
  List<int> region = [];
  for (int i = 0; i < data.length; i++) {
    double distance = math.sqrt(math.pow(data[i][0] - data[idx][0], 2) +
        math.pow(data[i][1] - data[idx][1], 2));
    if (distance <= eps) region.add(i);
  }
  return region;
}

