      int phaseMinutes = int.parse(phases[i]);
      if ((minute - count) % phaseMinutes == 0) {
        count++;
      }
    }

    if (count == phases.length) {
      result.add('$minute:${minute.toString().padLeft(2, '0')}');
    }

    minute += lcm;
  }

  return result;
}

