  final List<Map<String, Object>> undoStack = <Map<String, Object>>[];
  final int maxFee = 0;
  int totalDeposit = 0;
  int totalFee = 0;
  int totalWithdrawal = 0;
  int totalNetChange = 0;

  for (final String op in operations) {
    final List<String> parts = op.split(' ');
    final String type = parts[0];

    if (type == 'DEPOSIT') {
      final String currency = parts[1];
      final int value = int.parse(parts[2]);
      totalDeposit += value;
      amounts[currency] = (amounts[currency] ?? 0) + value;
      final Map<String, Object> entry = <String, Object>{
        'type': 'DEPOSIT',
        'currency': currency,
        'value': value,
      };
      undoStack.add(entry);
    } else if (type == 'WITHDRAW') {
      final String currency = parts[1];
      final int value = int.parse(parts[2]);
      int available = amounts[currency] ?? 0;
      if (available >= value) {
        totalWithdrawal += value;
        amounts[currency] = available - value;
        final Map<String, Object> entry = <String, Object>{
          'type': 'WITHDRAW',
          'currency': currency,
          'value': value,
        };
        undoStack.add(entry);
      }
    } else if (type == 'FEE') {
      final String currency = parts[1];
      final int value = int.parse(parts[2]);
      final int adjusted = fees[currency] ?? 0 + value;
      if (adjusted > maxFee) {
        fees[currency] = adjusted;
        totalFee += value;
      }
    } else if (type == 'UNDO') {
      if (undoStack.isNotEmpty) {
        final Map<String, Object> entry = undoStack.removeLast();
        final String entryType = entry['type'] as String;
        if (entryType == 'DEPOSIT') {
          final String currency = entry['currency'] as String;
          final int value = entry['value'] as int;
          amounts[currency] = (amounts[currency] ?? 0) - value;
          totalDeposit -= value;
        } else if (entryType == 'WITHDRAW') {
          final String currency = entry['currency'] as String;
          final int value = entry['value'] as int;
          amounts[currency] = (amounts[currency] ?? 0) + value;
          totalWithdrawal -= value;
        }
      }
    }

    final Set<String> availableCurrencies = <String>{};
    for (final int amt in amounts.values) {
      if (amt > 0) {
        availableCurrencies.add(amt.toString());
      }
    }
    final Set<String> activeFees = <String>{};
    for (final int fee in fees.values) {
      if (fee > 0) {
        activeFees.add(fee.toString());
      }
    }
    final int netChange = totalDeposit - totalWithdrawal - totalFee;
    totalNetChange += netChange;

    final Map<String, int> result = <String, int>{
      'totalDeposit': totalDeposit,
      'totalWithdrawal': totalWithdrawal,
      'totalFee': totalFee,
      'totalNetChange': totalNetChange,
      'availableCurrencies': availableCurrencies.length,
      'activeFees': activeFees.length,
    };
