  for (String op in operations) {
    List<String> parts = op.split(' ');
    if (parts[0] == 'DECK') {
      int num = int.parse(parts[1]);
      deck = [];
      maxSeq = 0;
      counts = {};
      for (int i = 1; i <= num; i++) {
        deck.add(i);
        counts[i.toString()] = 1;
        maxSeq++;
      }
    } else if (parts[0] == 'DRAW') {
      int index = int.parse(parts[1]);
      if (index < 1 || index > deck.length) {
        undoStack.add('DRAW:$index');
        continue;
      }
      int drawn = deck[index - 1];
      counts[drawn.toString()] = counts[drawn.toString()]! - 1;
      if (counts[drawn.toString()] == 0) {
        counts.remove(drawn.toString());
        if (counts.isEmpty) {
          maxSeq = 0;
        } else {
          maxSeq = counts.keys.map(int.parse).reduce((a, b) => a > b ? a : b);
        }
      }
      undoStack.add('DRAW:$index');
    } else if (parts[0] == 'UNDRAW') {
      if (undoStack.isEmpty) continue;
      String last = undoStack.removeLast();
      if (last.startsWith('DRAW:')) {
        String[] split = last.split(':');
        int index = int.parse(split[1]);
        int drawn = deck[index - 1];
        counts[drawn.toString()] = counts[drawn.toString()]! + 1;
        if (counts[drawn.toString()] == 1) {
          if (drawn > maxSeq) maxSeq = drawn;
        }
      }
    } else if (parts[0] == 'REVERSE') {
      deck = deck.reversed.toList();
      undoStack.add('REVERSE');
    } else if (parts[0] == 'SHUFFLE') {
      List<int> shuffled = [];
      while (deck.isNotEmpty) {
        int idx = (maxSeq + 1) % deck.length;
        shuffled.add(deck.removeAt(idx));
      }
      deck = shuffled;
      undoStack.add('SHUFFLE');
    }
  }
  return [deck.length, maxSeq, counts.length];
}

