bool fn0(String word, int k) {
  if (k < 0 || k > word.length) return false;
  final Map<int, int> freq = {};
  int left = 0;
  int required = k;
  int bestStart = 0, bestEnd = 0;
  for (int right = 0; right < word.length; right++) {
    int c = word.codeUnitAt(right);
    freq[c] = (freq[c] ?? 0) + 1;
    if (c < 97) required--;
    while (required == 0 && left <= right) {
      int len = right - left + 1;
      if (len > 26) return false;
      if (len < (bestEnd - bestStart + 1)) {
        bestStart = left;
        bestEnd = right;
      }
      int lc = word.codeUnitAt(left);
      if (lc < 97) required++;
      freq[lc] = freq[lc]! - 1;
      if (freq[lc] == 0) freq.remove(lc);
      left++;
    }
  }
  return bestEnd - bestStart + 1 == k;
}

