void fn0(List<String> args) {


  int n = args.isNotEmpty ? int.tryParse(args[0]) ?? 8 : 8;
  final List<int> board = List<int>.filled(n * n, 0);
  final int[] positions = [0, 1, 2, 3, 4, 5, 6, 7];

  int heuristic(int index) {
    int h = 0;
    for (int i = 0; i < index; i++) {
      int fileDist = (board[i] - board[index]).abs();
      int rankDist = (i ~/ n - index ~/ n).abs();
      h += fileDist > rankDist ? fileDist : rankDist;
    }
    return h;
  }

  int bestMove(int index) {
    int best = -1;
    int bestH = n;
    for (int p in positions) {
      if (p == board[index]) continue;
      board[index] = p;
      int h = heuristic(index);
      if (h < bestH) {
        bestH = h;
        best = p;
      }
      board[index] = 0;
    }
    return best;
  }

  void search(int index) {
    if (index == n) {

      int score = 0;
      for (int i = 0; i < n; i++) {
        int file = board[i];
        int rank = i ~/ n;
        for (int j = 0; j < n; j++) {
          if (board[j] == file && j ~/ n > rank) {
            score++;
          }
        }
      }
      print('Solution found: $board');
      print('Number of attacking pairs: $score');
      return;
    }
    int best = bestMove(index);
    for (int p in positions) {
      if (p == board[index]) continue;
      board[index] = p;
      if (index < n - 1) {
        search(index + 1);
      } else {
        int h = heuristic(index);
        if (h == 0) {
          print('Solution found: $board');
          print('Number of attacking pairs: 0');
        }
      }
      board[index] = 0;
    }
  }

  search(0);
}

