  bool satisfiesAvg = avg >= minHigh && avg <= maxLow;

  Set<int> result = <int>{};
  if (satisfiesWindow && satisfiesBorders && satisfiesAvg) {
    result.add(first);
    result.add(last);
    result.add(avg);
    result.add(windowAvg);
  }
  return result;
}

