    } else if (c.codeUnitAt(0) >= 97 && c.codeUnitAt(0) <= 122) {
      lowercase++;
    } else if (c.codeUnitAt(0) >= 65 && c.codeUnitAt(0) <= 90) {
      uppercase++;
    } else {
      symbols++;
    }
  }
  int total = digits + lowercase + uppercase + symbols;
  int result = 0;
  if (digits >= 2) {
    result += 2;
  }
  if (lowercase >= 2) {
    result += 2;
  }
  if (uppercase >= 2) {
    result += 2;
  }
  if (symbols >= 2) {
    result += 2;
  }
  if (total >= 10) {
    result += 3;
  }
  return result;
}

