List<int> fn0(List<int> rolls, int maxReroll, int seed) {
  int n = rolls.length;
  List<int> dp = List<int>.filled(n + 1, 0);
  List<int> nextDp = List<int>.filled(n + 1, 0);
  int state = seed % 4;
  int carry = 0;
  for (int i = 0; i < n; i++) {
    int r = rolls[i];
    int die = (state ^ r ^ carry) % 6;
    int reroll = (die < 2) ? 1 : 0;
    carry = reroll;
    if (reroll > maxReroll) {
      for (int v = 0; v <= 6; v++) nextDp[v] = -1000000;
    } else {
      for (int prev = 1; prev <= 6; prev++) {
        for (int v = 0; v <= 6; v++) {
          if (nextDp[v] < dp[prev] + (v == die ? prev : reroll + v)) nextDp[v] = dp[prev] + (v == die ? prev : reroll + v);
        }
      }
    }
    dp = nextDp;
    nextDp = List<int>.filled(n + 1, 0);
    state = (state + die) % 4;
  }
  int best = 0;
  for (int v = 0; v <= 6; v++) {
    if (dp[v] > dp[best]) best = v;
  }
  return [best, dp[best]];
}

