int fn0(List<int> playlist, int startDay, int endDay) {
  if (endDay < startDay || playlist.length < 2) return 0;
  const int k = 3;

  List<List<int>> prefix = [];
  for (int i = 0; i < playlist.length - 1; i++) {
    int diff = playlist[i + 1] - playlist[i];
    if (diff < 0) diff += 24;
    prefix.add([i, i + 1, diff]);
  }

  int n = prefix.length;
  List<int> maxS = List.filled(n + 1, 0);
  List<int> minS = List.filled(n + 1, 24);
  List<int> sumS = List.filled(n + 1, 0);
  List<int> lenS = List.filled(n + 1, 0);
  List<int> maxQ = List.filled(n + 1, 0);
  List<int> minQ = List.filled(n + 1, 24);
  List<int> sumQ = List.filled(n + 1, 0);
  List<int> lenQ = List.filled(n + 1, 0);

  for (int i = 0; i < n; i++) {
    int hi = i + k - 1;
    if (hi >= n) hi = n - 1;
    int left = i;
    int right = hi;
    int qStart = i - k + 1;
    if (qStart < 0) qStart = 0;
    int qEnd = i;
    if (qEnd >= n) qEnd = n - 1;

    for (int j = left; j <= right; j++) {
      int val = prefix[j][2];
      if (val > maxS[j + 1]) maxS[j + 1] = val;
      if (val < minS[j + 1]) minS[j + 1] = val;
      sumS[j + 1] += val;
      lenS[j + 1]++;
    }

    for (int j = qStart; j <= qEnd; j++) {
      int val = prefix[j][2];
      if (val > maxQ[j + 1]) maxQ[j + 1] = val;
      if (val < minQ[j + 1]) minQ[j + 1] = val;
      sumQ[j + 1] += val;
      lenQ[j + 1]++;
    }
  }

  int total = 0;
  for (int i = 0; i < n; i++) {
    int len = lenS[i + 1];
    if (len < k) continue;
    int maxLen = maxQ[i + 1];
    int minLen = minQ[i + 1];
    int diff = (maxLen - minLen) % 24;
    if (diff == 0) {
      total++;
    }
  }
  return total;
}

