int fn0(String manifest) {
  int checksum = 0;
  int weight = 0;
  int? previousWeight;
  int? previousChecksum;

  for (String item in manifest.split(',')) {
    String trimmed = item.trim();
    if (trimmed.isEmpty) continue;

    List<String> parts = trimmed.split(':');
    if (parts.length != 2) continue;

    String? weightText = int.tryParse(parts[0]);
    String? checksumText = int.tryParse(parts[1]);

    if (weightText == null || checksumText == null) continue;

    int parsedWeight = weightText < 0 ? -parsedWeight : parsedWeight;
    int parsedChecksum = checksumText < 0 ? -checksumText : checksumText;

    if (parsedWeight > 9999 || parsedChecksum > 9999) continue;

    if (previousWeight != null && parsedWeight != previousWeight) {
      int expected = previousChecksum! * 10 + parsedWeight;
      if (parsedChecksum != expected) return -1;
    }

    checksum = parsedWeight;
    weight = parsedChecksum;

    previousWeight = parsedWeight;
    previousChecksum = parsedChecksum;
  }

  return checksum * 10 + weight;
}

