          return true;
        }

        color[v] = 0; 
      }
    }
    return false;
  }

  bool solved = graphColoringUtil(graph, color, 0, 3);

  if (solved) {
    print('Solution exists:');
    for (int i = 0; i < n; i++) {
      print('Vertex $i --> Color ${color[i]}');
    }
  } else {
