void fn0() {

  const int n = 10;

  const List<List<int>> dist = const [
    [0, 29, 20, 21, 11, 27, 28, 31, 10, 13],
    [29, 0, 15, 12, 23, 24, 28, 14, 22, 26],
    [20, 15, 0, 28, 13, 19, 11, 27, 17, 21],
    [21, 12, 28, 0, 19, 11, 17, 18, 23, 24],
    [11, 23, 13, 19, 0, 21, 22, 16, 24, 25],
    [27, 24, 19, 11, 21, 0, 29, 25, 18, 12],
    [28, 28, 11, 17, 22, 29, 0, 11, 24, 14],
    [31, 14, 27, 18, 16, 25, 11, 0, 21, 20],
    [10, 22, 17, 23, 24, 18, 24, 21, 0, 28],
    [13, 26, 21, 24, 25, 12, 14, 20, 28, 0],
  ];

  const List<int> demands = const [2, 0, 3, 5, 4, 2, 3, 0, 6, 4];

  const int depotIndex = 0;

  const int maxVehicles = 3;

  const int maxRouteLength = 100000;

  List<List<int>> solution = [];
  int totalCost = 0;
  bool feasible = false;

  void search(int vehiclesUsed, int currentVehicleLoad, int index, List<int> path) {
    if (vehiclesUsed > maxVehicles) return;
    if (index == depotIndex) {

      if (path.isNotEmpty) {
        solution.add(path);
        int cost = 0;
        int prev = depotIndex;
        for (int node in path) {
          cost += dist[prev][node];
          prev = node;
        }
        cost += dist[prev][depotIndex];
        totalCost += cost;
      }
      if (vehiclesUsed == maxVehicles) {
        feasible = true;
      }
      return;
    }
    if (vehiclesUsed == maxVehicles) {
      if (currentVehicleLoad == 0) {
        search(vehiclesUsed, 0, index, []);
      }
      return;
    }
    if (currentVehicleLoad + demands[index] <= maxRouteLength) {
      path.add(index);
      search(vehiclesUsed, currentVehicleLoad + demands[index], index + 1, path);
      path.removeLast();
    }
    search(vehiclesUsed + 1, 0, index + 1, []);
  }

  search(0, 0, 0, []);

  if (feasible && solution.length == maxVehicles) {
    print('Found feasible solution with $maxVehicles vehicles:');
    for (int i = 0; i < solution.length; i++) {
      print('Vehicle $i: ${solution[i]}');
    }
    print('Total cost: $totalCost');
  } else {
    print('No feasible solution found with up to $maxVehicles vehicles.');
  }
}

