bool isValid(List<int> board, int row, int col, int num) {
  for (int i = 0; i < 9; i++) {
    if (board[row * 9 + i] == num || board[i * 9 + col] == num) {
      return false;
    }
  }
  int startRow = row - row % 3;
  int startCol = col - col % 3;
  for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
      if (board[(startRow + i) * 9 + startCol + j] == num) {
        return false;
      }
    }
  }
  return true;
}

bool solve(List<int> board, int row = 0, int col = 0) {
  if (row == 9) {
    return true;
  }
  if (col == 9) {
    return solve(board, row + 1, 0);
  }
  if (board[row * 9 + col] != 0) {
    return solve(board, row, col + 1);
  }
  for (int num = 1; num <= 9; num++) {
    if (isValid(board, row, col, num)) {
      board[row * 9 + col] = num;
      if (solve(board, row, col + 1)) {
        return true;
      }
      board[row * 9 + col] = 0;
    }
  }
  return false;
}

