List<int> fn0(List<List<int>> grid) {
  int rows = grid.length;
  if (rows == 0) return [];
  int cols = grid[0].length;
  if (cols == 0) return [];

  List<int> result = [];
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  bool isValid(int r, int c) {
    return r >= 0 && r < rows && c >= 0 && c < cols;
  }

  void dfs(int r, int c, int depth) {
    if (!isValid(r, c) || visited[r][c]) return;
    visited[r][c] = true;
    if (depth > result.length) {
      result = List<int>.filled(depth, 1);
    } else {
      result[depth - 1]++;
    }
    int current = grid[r][c];
    if (current == 0) {
      dfs(r - 1, c, depth + 1);
      dfs(r + 1, c, depth + 1);
      dfs(r, c - 1, depth + 1);
      dfs(r, c + 1, depth + 1);
    } else {
      dfs(r - current, c, depth + 1);
      dfs(r + current, c, depth + 1);
      dfs(r, c - current, depth + 1);
      dfs(r, c + current, depth + 1);
    }
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      dfs(r, c, 1);
    }
  }

  return result;
}

