  void quickSort(List<int> arr, int low, int high) {
    if (low >= high) return;

    final int pivot = arr[high]; 
    int i = low; 
    int j = high - 1; 

    for (; i < j; i++, j--) {

      while (arr[i] < pivot) {
        i++;
      }

      while (arr[j] > pivot) {
        j--;
      }

      if (i < j) {
        final int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
    }

    final int temp = arr[i];
    arr[i] = arr[high];
    arr[high] = temp; 

    quickSort(arr, low, i - 1);
    quickSort(arr, i + 1, high);
  }

  quickSort(numbers, 0, numbers.length - 1);

  print('Sorted array: $numbers');
}

