    return -1.0;
  }

  int left = 0;
  int right = cycleDurations.length - 1;
  int result = -1;

  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int cycleLength = cycleDurations[mid];

    if (cycleLength >= targetDay) {
      result = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }

