@pragma('vm:entry-point')
Map<String, int> fn0(List<int> cycleLengths, int totalDays) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  int lcm(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (a ~/ gcd(a, b)) * b;
  }

  int gcdAll(List<int> xs) {
    int g = 0;
    for (int x in xs) {
      g = gcd(g, x);
    }
    return g;
  }

  int lcmAll(List<int> xs) {
    int l = 1;
    for (int x in xs) {
      if (x != 0) {
        l = lcm(l, x);
      }
    }
    return l;
  }

  int gcdSum = gcdAll(cycleLengths);
  int lcmSum = lcmAll(cycleLengths);
  int gcdOdd = gcdAll(cycleLengths.where((x) => x.isOdd).toList());
  int lcmEven = lcmAll(cycleLengths.where((x) => x.isEven).toList());

  int exactCycles = totalDays ~/ lcmSum;
  int remainder = totalDays % lcmSum;

  int fullCycleSum = exactCycles * (gcdSum + lcmSum + gcdOdd + lcmEven);
  int extraGcd = remainder % gcdSum;
  int extraLcm = remainder % lcmSum;
  int extraSum = extraGcd + extraLcm + gcdOdd + lcmEven;
  int finalSum = fullCycleSum + extraSum;

  return {
    'gcdSum': gcdSum,
    'lcmSum': lcmSum,
    'gcdOdd': gcdOdd,
    'lcmEven': lcmEven,
    'exactCycles': exactCycles,
    'remainder': remainder,
    'fullCycleSum': fullCycleSum,
    'extraSum': extraSum,
    'finalSum': finalSum,
  };
}

