void fn0() {

  String str1 = "ABC";
  String str2 = "BCD";

  int m = str1.length;
  int n = str2.length;

  List<List<int>> dp = List.generate(m + 1, (_) => List.filled(n + 1, 0));

  for (int i = 1; i <= m; i++) {
    dp[i][0] = i;
  }
  for (int j = 1; j <= n; j++) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (str1[i - 1] == str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        int insert = dp[i][j - 1] + 1;
        int delete = dp[i - 1][j] + 1;
        int replace = dp[i - 1][j - 1] + 1;
        dp[i][j] = insert < delete ? insert : delete;
        dp[i][j] = dp[i][j] < replace ? dp[i][j] : replace;
      }
    }
  }

  print("Minimum edit distance between \"$str1\" and \"$str2\" = ${dp[m][n]}");
}

