int fn0(String password, int maxSegments) {
  if (password.isEmpty) return 0;
  if (password.length == 1) return 1;

  final Map<int, int> memo = {};

  int solve(int start, int remainingSegments) {
    if (start == password.length) {
      return 0;
    }
    if (remainingSegments == 0) {
      return -1;
    }
    if (memo.containsKey(start)) {
      return memo[start]!;
    }

    int best = -1;
    int currentRun = 1;
    int currentChar = password.codeUnitAt(start);

    for (int end = start + 1; end < password.length; end++) {
      int nextChar = password.codeUnitAt(end);
      if (nextChar == currentChar) {
        currentRun++;
      } else {
        currentRun = 1;
        currentChar = nextChar;
      }

      int nextBest = solve(end, remainingSegments - 1);
      if (nextBest != -1) {
        int total = currentRun + nextBest;
        if (total > best) {
          best = total;
        }
      }
    }

    int singleBest = solve(start + 1, remainingSegments - 1);
    if (singleBest != -1) {
      if (singleBest > best) {
        best = singleBest;
      }
    }

    memo[start] = best;
    return best;
  }

  return solve(0, maxSegments);
}

