  int peakMinutes = 0;
  int overlappingMinutes = 0;
  int gaps = 0;

  for (int i = 0; i < startTimes.length; i++) {
    int end = startTimes[i] + durations[i];
    int count = (intervals[end] ?? 0) + 1;
