      peakMinutes = count;
    }
    if (count == 0) {
      totalDuration += end - startTimes[i];
    }
  }

  int maxGap = 0;
  int currentGap = 0;
  int lastEnd = 0;
  List<int> sortedStarts = List.from(startTimes)..sort();
  List<int> sortedEnds = List.from(startTimes)..sort((a, b) => (startTimes[a] + durations[a]).compareTo(startTimes[b] + durations[b]));

  for (int i = 0; i < sortedEnds.length; i++) {
    int end = sortedEnds[i];
    if (i == 0) {
      currentGap = end - lastEnd;
      if (currentGap > maxGap) maxGap = currentGap;
    } else {
