  int i = 0;
  int prevDigit = -1;
  while (i < password.length) {
    String ch = password[i];
    if (state == 0) {
      if (ch == '#') {
        state = 1;
        i++;
      } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        state = 2;
        prevDigit = ch.codeUnitAt(0) - 48;
        i++;
      } else {
