      }
    } else if (state == 1) {
      if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        prevDigit = ch.codeUnitAt(0) - 48;
        i++;
      } else {
        return {};
      }
    } else if (state == 2) {
      if (ch == '#') {
        state = 0;
        i++;
      } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        prevDigit = ch.codeUnitAt(0) - 48;
        i++;
      } else {
        return {};
      }
    }
  }
  if (state != 0) return {};
  if (prevDigit == -1) return {};
  for (int j = 1; j * j <= prevDigit; j++) {
    if (prevDigit % j == 0) {
      result.add(j);
      int complement = prevDigit ~/ j;
      if (complement != j && complement > 1) result.add(complement);
    }
  }
  result.remove(1);
  return result;
}

