Map<String, int> fn0(List<int> startTimes, List<int> endTimes, List<int> amounts, int maxTotalAmount) {
  int n = startTimes.length;
  List<int> dp = List.filled(n + 1, 0);
  List<List<int>> events = [];
  for (int i = 0; i < n; i++) {
    events.add([startTimes[i], amounts[i], 0]);
    events.add([endTimes[i], -amounts[i], 1]);
  }
  events.sort((a, b) {
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    if (a[1] != b[1]) return b[1].compareTo(a[1]);
    return a[2].compareTo(b[2]);
  });
  int total = 0;
  for (int i = 0; i <= n; i++) {
    dp[i] = total <= maxTotalAmount ? total : -1000000;
  }
  int curTime = 0;
  for (List<int> e in events) {
    int t = e[0], amt = e[1], type = e[2];
    if (type == 0) {
      total += amt;
    } else {
      total -= amt;
    }
    if (curTime < t) {
      int lo = total <= maxTotalAmount ? total : -1000000;
      int hi = (total + (t - curTime) * 1000) <= maxTotalAmount ? (total + (t - curTime) * 1000) : -1000000;
      for (int i = curTime; i < t; i++) {
        for (int j = 0; j < n; j++) {
          if (dp[j] != -1000000) {
            lo = lo < dp[j] + (t - i) * 1000 ? lo : dp[j] + (t - i) * 1000;
            hi = hi > dp[j] + (t - i) * 1000 ? hi : dp[j] + (t - i) * 1000;
          }
        }
      }
      for (int j = 0; j < n; j++) {
        if (dp[j] != -1000000) {
          dp[j] = dp[j] < lo ? dp[j] : lo;
          dp[j] = dp[j] > hi ? dp[j] : hi;
        }
      }
      curTime = t;
    }
  }
  int best = -1000000;
  int bestLen = -1;
  for (int j = 0; j < n; j++) {
    if (dp[j] != -1000000 && dp[j] > best) {
      best = dp[j];
      bestLen = j;
    } else if (dp[j] != -1000000 && dp[j] == best) {
      if (j < bestLen) bestLen = j;
    }
  }
  return {bestLen.toString(): best};
}

