int fn0(List<int> startTimes, List<int> durations, int queryHour) {
  if (startTimes.length != durations.length) {
    throw ArgumentError('startTimes and durations must have the same length');
  }

  int left = 0;
  int right = startTimes.length;

  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (startTimes[mid] + durations[mid] > queryHour) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }

  if (left == 0) {
    return -1;
  }

  int previousEnd = startTimes[left - 1] + durations[left - 1];

  if (previousEnd > queryHour) {
    return left - 1;
  }

  return -1;
}

