String fn0(List<String> operations) {
  List<String> stack = [];
  List<String> maxStack = [];
  List<String> minStack = [];
  List<String> history = [];
  List<String> undone = [];

  for (String op in operations) {
    if (op == 'undo') {
      if (undone.isNotEmpty) {
        String last = undone.removeLast();
        if (last == 'undo') {
          stack.removeLast();
          maxStack.removeLast();
          minStack.removeLast();
        } else {
          stack.add(last);
          maxStack.add(maxStack.last);
          minStack.add(minStack.last);
        }
      }
    } else if (op.startsWith('add:')) {
      String value = op.substring(4);
      stack.add(value);
      if (maxStack.isEmpty || value.compareTo(maxStack.last) > 0) {
        maxStack.add(value);
      } else {
        maxStack.add(maxStack.last);
      }
      if (minStack.isEmpty || value.compareTo(minStack.last) < 0) {
        minStack.add(value);
      } else {
        minStack.add(minStack.last);
      }
      undone.clear();
      history.add(value);
    } else if (op == 'undo:undo') {
      undone.add('undo');
    }
  }

  if (stack.isEmpty) return 'history: <none>';
  List<String> elements = [];
  for (String val in stack) {
    if (val != 'undo') {
      elements.add(val);
    }
  }
  return 'history: ${history.join(", ")}; current: ${elements.join(", ")}';
}

