double fn0(List<List<int>> rounds, int targetSum) {
  if (rounds.isEmpty) {
    return 0.0;
  }

  int totalPlayers = 0;
  for (var round in rounds) {
    totalPlayers = round.length;
  }

  int totalGames = 0;
  for (var round in rounds) {
    for (var score in round) {
      totalGames += score;
    }
  }

  int roundIndex = -1;
  for (var i = 0; i < rounds.length; i++) {
    var round = rounds[i];
    int prefixSum = 0;
    for (var score in round) {
      prefixSum += score;
      if (prefixSum == targetSum) {
        roundIndex = i;
        break;
      }
      if (prefixSum > targetSum) {
        break;
      }
    }
    if (roundIndex != -1) {
      break;
    }
  }

  if (roundIndex == -1) {
    return 0.0;
  }

  int playersInRound = rounds[roundIndex].length;
  int gamesUpToRound = 0;
  for (var i = 0; i < roundIndex; i++) {
    gamesUpToRound += rounds[i].fold(0, (a, b) => a + b);
  }

  return ((totalPlayers - playersInRound) / (totalPlayers.toDouble() - 1.0)) *
      ((gamesUpToRound + 1.0) / totalGames);
}

