  if (width * 4 != encodedGrid.length) {
    return 0.0;
  }

  final Map<String, String> binToChar = {
    '00': 'A', '01': 'C', '10': 'G', '11': 'T'
  };
  double totalQuality = 0.0;
  int positions = 0;

  for (int i = 0; i < encodedGrid.length; i += 4) {
    final String bin = encodedGrid.substring(i, i + 2);
    final String qual = encodedGrid.substring(i + 2, i + 3);
