      totalQuality += qualVal * 1.5;
      positions++;
    } else if (base == 'G' && qualVal >= 6) {
      totalQuality += qualVal * 2.0;
      positions++;
    }
  }

  if (positions == 0) return 0.0;
  return totalQuality / positions;
}

