int fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<int>> memo = List.generate(rows, (_) => List.filled(cols, -1));
  int dfs(int r, int c) {
    if (r < 0 || c < 0 || r >= rows || c >= cols) return 0;
    if (memo[r][c] != -1) return memo[r][c];
    int maxLen = 1;
    int val = grid[r][c];
    if (r > 0 && grid[r - 1][c] == val + 1) {
      int len = 1 + dfs(r - 1, c);
      maxLen = len > maxLen ? len : maxLen;
    }
    if (r < rows - 1 && grid[r + 1][c] == val + 1) {
      int len = 1 + dfs(r + 1, c);
      maxLen = len > maxLen ? len : maxLen;
    }
    if (c > 0 && grid[r][c - 1] == val + 1) {
      int len = 1 + dfs(r, c - 1);
      maxLen = len > maxLen ? len : maxLen;
    }
    if (c < cols - 1 && grid[r][c + 1] == val + 1) {
      int len = 1 + dfs(r, c + 1);
      maxLen = len > maxLen ? len : maxLen;
    }
    memo[r][c] = maxLen;
    return maxLen;
  }
  int maxChain = 0;
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int chainLen = dfs(i, j);
      if (chainLen > maxChain) maxChain = chainLen;
    }
  }
  return maxChain;
}

