int fn0(List<String> passwords, String target) {
  if (passwords.isEmpty) {
    return -1;
  }

  int search(String word, int low, int high) {
    if (low > high) {
      return -1;
    }

    int mid = (low + high) ~/ 2;

    String midWord = passwords[mid];
    if (midWord == target) {
      return mid;
    }

    int targetLeetIdx = -1;
    int midLeetIdx = -1;
    for (int i = 0; i < target.length; i++) {
      int code = target.codeUnitAt(i);
      if (code >= 97 && code <= 122) {
        targetLeetIdx = i;
        break;
      }
    }

    for (int i = 0; i < midWord.length; i++) {
      int code = midWord.codeUnitAt(i);
      if (code >= 97 && code <= 122) {
        midLeetIdx = i;
        break;
      }
    }

    if (targetLeetIdx == -1 && midLeetIdx != -1) {
      return search(word, low, mid - 1);
    }

    if (midLeetIdx == -1 && targetLeetIdx != -1) {
      return search(word, mid + 1, high);
    }

    int comparison = target.compareTo(midWord);
    if (comparison < 0) {
      return search(word, low, mid - 1);
    } else {
      return search(word, mid + 1, high);
    }
  }

  return search('', 0, passwords.length - 1);
}

