Set<int> fn0(List<int> cycleMinutes, int intervalMinutes) {
  final Set<int> result = <int>{};
  if (intervalMinutes <= 0) {
    return result;
  }
  int g = 0;
  for (final int m in cycleMinutes) {
    g = _gcd(g, m);
  }
  if (g != 1) {
    return result;
  }
  for (final int m in cycleMinutes) {
    int a = m;
    int b = intervalMinutes;
    while (b != 0) {
      final int t = a ~/ b;
      final int tmp = a;
      a = b;
      b = tmp % b;
    }
    final int inverse = a == 1 ? (intervalMinutes % m) : -1;
    if (inverse == -1) {
      continue;
    }
    int remainder = intervalMinutes % m;
    int k = (1 - remainder) ~/ inverse;
    if (k < 0) {
      k += m;
    }
    result.add(k);
  }
  return result;
}

int _gcd(int a, int b) {
  while (b != 0) {
    final int t = a ~/ b;
    final int tmp = a;
    a = b;
    b = tmp % b;
  }
  return a;
}

