List<String> fn0(List<List<int>> grid) {
  if (grid.isEmpty) return [];
  int rows = grid.length;
  int cols = grid[0].length;
  List<String> result = [];
  int left = 0;
  int right = cols - 1;
  int top = 0;
  int bottom = rows - 1;
  while (left <= right && top <= bottom) {
    List<int> perimeter = [];
    for (int c = left; c <= right; c++) perimeter.add(grid[top][c]);
    for (int r = top + 1; r <= bottom; r++) perimeter.add(grid[r][right]);
    if (top + 1 <= bottom) {
      for (int c = right - 1; c >= left; c--) perimeter.add(grid[bottom][c]);
    }
    if (top <= bottom - 1) {
      for (int r = bottom - 1; r > top; r--) perimeter.add(grid[r][left]);
    }
    int gcdVal = 1;
    for (int i = 0; i < perimeter.length; i++) {
      int a = gcdVal;
      int b = perimeter[i];
      while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
      }
      gcdVal = a;
    }
    String label = 'R$top,C$left';
    if (left < right) label += 'x$cols';
    if (top < bottom) label += '+$rows';
    result.add('$label:$gcdVal');
    left++;
    right--;
    top++;
    bottom--;
  }
  return result;
}

