            int root1 = findRoot(idx), root2 = findRoot(nei);
            if (root1 != root2) {
              parent[root1] = root2;
              result.remove(regionSize(root1));
              int? s1 = regionSize(root1), s2 = regionSize(root2);
              if (s1 != null && s2 != null) {
