void fn0() {



  final List<List<double>> points = [
    [1.0, 2.0],
    [2.0, 2.0],
    [3.0, 3.0],
    [6.0, 7.0],
    [6.0, 8.0],
    [7.0, 8.0],
    [8.0, 8.0],
    [9.0, 8.0],
    [9.0, 9.0],
    [10.0, 9.0],
  ];

  const double maxDistance = 1.5;

  Map<int, List<int>> clusters = {};
  for (int i = 0; i < points.length; i++) {
    clusters.putIfAbsent(i, () => [i]);
  }

  while (true) {
    bool anyMerged = false;

    Map<int, List<int>> newClusters = {};
    for (int clusterId in clusters.keys) {
      List<int> members = clusters[clusterId]!;
      if (members.length == 1) {
        newClusters[clusterId] = members;
        continue;
      }

      bool foundMerge = false;
      for (int otherId in clusters.keys) {
        if (otherId == clusterId) continue;
        List<int> otherMembers = clusters[otherId]!;
        if (otherMembers.length == 1) {

          bool shouldMerge = true;
          for (int p1 in members) {
            for (int p2 in otherMembers) {
              double dx = (points[p1][0] - points[p2][0]).abs();
              double dy = (points[p1][1] - points[p2][1]).abs();
              if (sqrt(dx * dx + dy * dy) > maxDistance) {
                shouldMerge = false;
                break;
              }
            }
            if (!shouldMerge) break;
          }

          if (shouldMerge) {
            newClusters[clusterId] = List<int>.from(members)..addAll(otherMembers);
            anyMerged = true;
            foundMerge = true;
            break;
          }
        }
      }
      if (!foundMerge) {
        newClusters[clusterId] = members;
      }
    }

    if (!anyMerged) break;

    clusters = newClusters;
  }

  for (int clusterId in clusters.keys) {
    List<int> members = clusters[clusterId]!;
    print('Cluster $clusterId: ${members.map((i) => '[${points[i][0]}, ${points[i][1]}]').join(', ')}');
  }
}

