List<String> fn0(String encoded) {
  if (encoded.isEmpty) return [];
  List<String> result = [];
  int i = 0;
  int total = 0;

  while (i < encoded.length) {
    int count = 0;
    bool isDigit = false;
    while (i < encoded.length && ((isDigit && encoded[i].codeUnitAt(0) >= 48 && encoded[i].codeUnitAt(0) <= 57) || (!isDigit && (encoded[i].codeUnitAt(0) >= 65 && encoded[i].codeUnitAt(0) <= 90)))) {
      if (encoded[i].codeUnitAt(0) >= 48 && encoded[i].codeUnitAt(0) <= 57) {
        count = count * 10 + (encoded[i].codeUnitAt(0) - 48);
        isDigit = true;
      } else {
        count++;
        isDigit = false;
      }
      i++;
    }

    if (i >= encoded.length || encoded[i] != 'x') {
      return [];
    }
    i++;

    int start = i;
    int runLength = 0;
    bool inRun = false;
    while (i < encoded.length) {
      if (encoded[i].codeUnitAt(0) >= 48 && encoded[i].codeUnitAt(0) <= 57) {
        int digitVal = encoded[i].codeUnitAt(0) - 48;
        if (runLength > 127) return [];
        runLength = runLength * 10 + digitVal;
        i++;
      } else if (encoded[i] == 'r') {
        if (!inRun) return [];
        i++;
        while (i < encoded.length && encoded[i].codeUnitAt(0) >= 48 && encoded[i].codeUnitAt(0) <= 57) {
          runLength = runLength * 10 + (encoded[i].codeUnitAt(0) - 48);
          i++;
        }
        if (i < encoded.length && encoded[i] == 'x') {
          i++;
        }
        break;
      } else {
        inRun = true;
        i++;
      }
    }

    if (start == i) return [];
    String chr = encoded.substring(start, i);
    if (chr.length > 1) return [];

    if (chr == 'r') {
      result.add('R' + (runLength > 1 ? '*$runLength' : ''));
    } else {
      int code = chr.codeUnitAt(0);
      int shift = (code + count) % 26;
      int orig = (shift < 13 ? 65 + shift : 65 + (shift - 13) + 13);
      result.add(String.fromCharCode(orig) + (runLength > 1 ? '*$runLength' : ''));
    }

    total += runLength;
  }

  return total % 2 == 0 ? result : [];
}

