Set<int> fn0(List<List<int>> grid) {
  if (grid.isEmpty) {
    return <int>{};
  }
  int rows = grid.length;
  int cols = grid[0].length;
  if (cols == 0) {
    return <int>{};
  }

  List<int> dp = List<int>.filled(cols, 1);
  int maxLen = 1;

  for (int r = 1; r < rows; r++) {
    List<int> nextDp = List<int>.filled(cols, 1);
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] > grid[r - 1][c]) {
        int best = 1;
        for (int prevC = c - 1; prevC <= c + 1; prevC++) {
          if (prevC >= 0 && prevC < cols) {
            if (grid[r][c] > grid[r - 1][prevC]) {
              if (nextDp[prevC] + 1 > best) {
                best = nextDp[prevC] + 1;
              }
            }
          }
        }
        nextDp[c] = best;
        if (best > maxLen) {
          maxLen = best;
        }
      }
    }
    dp = nextDp;
  }

  Set<int> result = <int>{};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (dp[j] == maxLen) {
        result.add(grid[i][j]);
      }
    }
  }
  return result;
}

