List<String> fn0(List<int> cycleDurations, int totalMinutes) {
  if (cycleDurations.isEmpty || totalMinutes <= 0) {
    return [];
  }

  final int lcm = _lcm(cycleDurations);
  final List<String> result = [];
  int minute = 0;

  while (minute < totalMinutes) {
    final int count = _countCycleHits(cycleDurations, minute);
    if (count > 1) {
      result.add('${minute}:$count');
    }
    minute++;
  }

  return result;
}

int _lcm(List<int> numbers) {
  int currentLcm = numbers[0];
  for (int i = 1; i < numbers.length; i++) {
    currentLcm = (currentLcm * numbers[i]) ~/ _gcd(currentLcm, numbers[i]);
  }
  return currentLcm;
}

int _gcd(int a, int b) {
  while (b != 0) {
    final int temp = a % b;
    a = b;
    b = temp;
  }
  return a;
}

int _countCycleHits(List<int> cycleDurations, int minute) {
  int count = 0;
  for (final int duration in cycleDurations) {
    if (duration <= 0) continue;
    if (minute % duration == 0) count++;
  }
  return count;
}

