List<String> fn0(List<int> strengths, int threshold) {
  final result = <String>[];
  final n = strengths.length;
  if (n == 0) {
    return result;
  }

  const dead = -1;
  const alive = 1;
  final state = List<int>.filled(n, alive);

  for (var i = 0; i < n; i++) {
    if (strengths[i] < threshold) {
      state[i] = dead;
    }
  }

  var aliveCount = state.where((s) => s == alive).length;

  final int getRank(int index) {
    var rank = 0;
    for (var i = 0; i < n; i++) {
      if (state[i] == alive && strengths[i] > strengths[index]) {
        rank++;
      }
    }
    return rank;
  }

  final int getScore(int index) {
    var score = 0;
    for (var i = 0; i < n; i++) {
      if (state[i] == alive) {
        final diff = strengths[index] - strengths[i];
        score += diff > 0 ? diff : -diff;
      }
    }
    return score;
  }

  final int getDominance(int index) {
    int count = 0;
    for (var i = 0; i < n; i++) {
      if (state[i] == alive && strengths[i] < strengths[index]) {
        count++;
      }
    }
    return count;
  }

  final int getVictories(int index) {
    int count = 0;
    for (var i = 0; i < n; i++) {
      if (state[i] == alive && strengths[i] > strengths[index]) {
        count++;
      }
    }
    return count;
  }

  final bool isDominant(int index) {
    return getDominance(index) == aliveCount - 1;
  }

  for (var i = 0; i < n; i++) {
    if (state[i] == dead) {
      continue;
    }

    final rank = getRank(i);
    final score = getScore(i);
    final dominance = getDominance(i);
    final victories = getVictories(i);
    final isDom = isDominant(i);

    final suffix = isDom
        ? ' (Dominant)'
        : dominance == 0 ? ' (Defender)' : ' (Active)';

    result.add('Rank $rank, Score $score, '
        'Dominance $dominance/$aliveCount$(suffix)');
  }

  return result;
}

