  }
  Map<int, int> freq = {};
  for (int h in heights) {
    freq[h] = (freq[h] ?? 0) + 1;
  }
  Set<int> peaks = {};
  for (var entry in freq.entries) {
    if (entry.key > 0 && (peaks.isEmpty || !peaks.contains(entry.key))) {
      bool isPrime = true;
      for (int d = 2; d * d <= entry.value; d++) {
        if (entry.value % d == 0) {
          isPrime = false;
          break;
        }
      }
      if (isPrime) {
        peaks.add(entry.key);
      }
    }
  }
  return peaks;
}

