    int played = minRounds + maxRounds - 1;
    totalChips = total;
    chipsPerRound = total ~/ played;
    remainingChips = total % played;
  } else {
    int total = sorted.take(n).fold(0, (sum, s) => sum + s);
    int roundEnd = minRounds + maxRounds - 1;
    int played = maxRounds - minRounds + 1;
    totalChips = total;
    chipsPerRound = total ~/ played;
    remainingChips = total % played;
  }

