void fn0() {

  List<List<int>> dists = [
    [0,  10, 15, 20],
    [10, 0,  35, 25],
    [15, 35, 0,  30],
    [20, 25, 30, 0]
  ];

  int n = dists.length;

  List<int> cost = List.filled(n, 0);
  List<int> count = List.filled(n, 0);

  for (int i = 0; i < n; i++) {
    int sum = 0;
    for (int j = 0; j < n; j++) {
      if (j != i) {
        sum += dists[i][j];
      }
    }
    cost[i] = sum;
    count[i] = n - 1;
  }

  int bestIndex = 0;
  int bestCost = cost[0];
  for (int i = 1; i < n; i++) {
    if (cost[i] < bestCost) {
      bestCost = cost[i];
      bestIndex = i;
    }
  }

  print('Best starting point: Node $bestIndex');
  print('Total distance: $bestCost');

  print('\nChecking all permutations...');
  int totalPerms = factorial(n - 1);
  int permCount = 0;

  void permute(int start, List<int> current, List<bool> used) {
    if (current.length == n - 1) {
      permCount++;
      int tourCost = 0;
      int prev = bestIndex;
      for (int node in current) {
        if (node == prev) {
          print('Invalid permutation: repeated node $node');
          return;
        }
        tourCost += dists[prev][node];
        prev = node;
      }
      tourCost += dists[prev][bestIndex]; 
      if (tourCost < bestCost) {
        bestCost = tourCost;
        print('New best: $tourCost (perm $permCount)');
      }
    } else {
      for (int i = 0; i < n; i++) {
        if (!used[i] && i != bestIndex) {
          used[i] = true;
          current.add(i);
          permute(start + 1, current, used);
          current.removeLast();
          used[i] = false;
        }
      }
    }
  }

  List<bool> used = List.filled(n, false);
  permute(0, [], used);

  print('\nBrute-force result:');
  print('Best cost: $bestCost');
  print('Total permutations checked: $permCount (max = $totalPerms)');
}

int factorial(int n) {
  int result = 1;
  for (int i = 1; i <= n; i++) {
    result *= i;
  }
  return result;
}

