  double sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;

  for (int i = 0; i < n; i++) {
    sumX += data[i];
    sumY += data[i] * data[i]; 
    sumXY += data[i] * data[i]; 
    sumX2 += data[i] * data[i]; 
  }

  double m = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  double b = (sumY - m * sumX) / n;

  print('Linear regression results:');
  print('Slope (m) = ${m.toStringAsFixed(4)}');
  print('Intercept (b) = ${b.toStringAsFixed(4)}');
  print('Equation: y = ${m.toStringAsFixed(4)}x + ${b.toStringAsFixed(4)}');

  print('\nPredictions:');
  for (int i = 0; i < n; i++) {
    double x = data[i];
    double yPred = m * x + b;
    print('x = $x → predicted y = ${yPred.toStringAsFixed(2)}');
  }

  double sumResiduals = 0;
  double sumPredicted = 0;
  double sumActual = 0;
  double sumSquaredErrors = 0;

  for (int i = 0; i < n; i++) {
    double x = data[i];
    double yActual = x * x;
    double yPred = m * x + b;
    sumResiduals += (yActual - yPred);
    sumPredicted += yPred;
    sumActual += yActual;
    sumSquaredErrors += pow(yActual - yPred, 2);
  }

  double meanPredicted = sumPredicted / n;
  double meanActual = sumActual / n;

  double mse = sumSquaredErrors / n;
  double rmse = sqrt(mse);
  double r2 = 1 - (sumSquaredErrors / ((sumActual * sumActual) / n - sumActual * meanActual + n * meanActual * meanActual));

  print('\nEvaluation metrics:');
  print('Mean Squared Error (MSE) = ${mse.toStringAsFixed(4)}');
  print('Root Mean Squared Error (RMSE) = ${rmse.toStringAsFixed(4)}');
  print('R-squared (R²) = ${r2.toStringAsFixed(4)}');

  double x0 = 80;
  double y0Pred = m * x0 + b;
  print('\nPrediction for x = $x0: y = ${y0Pred.toStringAsFixed(2)}');
}

