  final List<List<int>> dp = List.generate(n + 1, (_) => List.filled(maxW + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= maxW; w++) {

      if (weights[i - 1] <= w) {
        dp[i][w] = dp[i - 1][w - weights[i - 1]] > dp[i - 1][w] 
            ? dp[i - 1][w - weights[i - 1]] 
            : dp[i - 1][w];
        dp[i][w] = dp[i][w] > (values[i - 1] + dp[i - 1][w - weights[i - 1]]) 
            ? dp[i][w] 
            : values[i - 1] + dp[i - 1][w - weights[i - 1]];
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  int maxProfit = 0;
  for (int i = 0; i <= n; i++) {
    if (dp[i][maxW] > maxProfit) {
      maxProfit = dp[i][maxW];
