void fn0() {

  List<List<int>> graph = List.generate(5, (_) => []);

  graph[0].add(1);
  graph[0].add(2);
  graph[1].add(2);
  graph[2].add(0);
  graph[2].add(3);
  graph[3].add(4);

  bool isSafe(int v, List<bool> visited, List<List<int>> graph, List<bool> recursionStack) {
    visited[v] = true;
    recursionStack[v] = true;

    for (int neighbor in graph[v]) {
      if (!visited[neighbor]) {
        if (isSafe(neighbor, visited, graph, recursionStack)) {
          return true;
        }
      } else if (recursionStack[neighbor]) {
        return true;
      }
    }

    recursionStack[v] = false;
    return false;
  }

  List<bool> visited = List.filled(graph.length, false);
  List<bool> recursionStack = List.filled(graph.length, false);

  bool hasCycle = false;

  for (int i = 0; i < graph.length; i++) {
    if (!visited[i]) {
      if (isSafe(i, visited, graph, recursionStack)) {
        hasCycle = true;
        break;
      }
    }
  }

  if (hasCycle) {
    print('Graph contains a cycle');
  } else {
    print('Graph is acyclic');
  }
