List<int> fn0(List<int> cycleTemps, int target) {
  if (cycleTemps.isEmpty) return [-1, -1];

  List<int> solve(int lo, int hi) {
    if (lo == hi) {
      if (cycleTemps[lo] == target) return [lo, lo];
      return [-1, -1];
    }

    int mid = (lo + hi) ~/ 2;
    List<int> left = solve(lo, mid);
    if (left[0] != -1) return left;

    List<int> right = solve(mid + 1, hi);
    if (right[0] != -1) return right;

    int midVal = cycleTemps[mid];
    if (midVal == target) return [mid, mid];

    int leftVal = cycleTemps[lo];
    int rightVal = cycleTemps[hi];

    if (midVal > leftVal && midVal < rightVal) {
      return [lo, hi];
    }

    if (midVal > leftVal) {
      return solve(lo, mid);
    }

    return solve(mid + 1, hi);
  }

  List<int> result = solve(0, cycleTemps.length - 1);
  if (result[0] == -1) return [-1, -1];

  int lo = result[0], hi = result[1];
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (cycleTemps[mid] == target) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }

  return [lo, cycleTemps.indexOf(target, lo)];
}

