Map<String, int> fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return {"bonds": 0, "chains": 0};
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  int chains = 0;
  int bonds = 0;
  void dfs(int r, int c) {
    visited[r][c] = true;
    int current = grid[r][c];
    if (r > 0 && grid[r - 1][c] == current) bonds++;
    if (c > 0 && grid[r][c - 1] == current) bonds++;
    if (r < rows - 1 && grid[r + 1][c] == current) bonds++;
    if (c < cols - 1 && grid[r][c + 1] == current) bonds++;
    if (r > 0 && !visited[r - 1][c]) dfs(r - 1, c);
    if (c > 0 && !visited[r][c - 1]) dfs(r, c - 1);
    if (r < rows - 1 && !visited[r + 1][c]) dfs(r + 1, c);
    if (c < cols - 1 && !visited[r][c + 1]) dfs(r, c + 1);
  }
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        dfs(r, c);
        chains++;
      }
    }
  }
  int finalBonds = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      finalBonds += grid[r][c] == 1 ? 1 : 0;
    }
  }
  return {"bonds": finalBonds, "chains": chains};
}

