    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      digit = 1;
    } else {
      special = 1;
    }
  }

  int strength = 1;
  if (lowercase == 0 || uppercase == 0 || digit == 0 || special == 0) strength = 2;

  if (strength == 1) return 'Very Weak';
  if (strength == 2) return 'Weak';

  if (password.length < 8) {
