    String ch = password[i];
    if (ch == prevPattern) {
      runLength++;
      if (runLength >= 2) {
        return 'Weak';
      }
    } else {
      prevPattern = ch;
      runLength = 1;
    }
  }

  for (int i = 0; i < password.length - 2; i++) {
    String a = password[i], b = password[i + 1], c = password[i + 2];
    if (a == b && b == c) {
