        return 'Weak';
      }
    }
  }

  int bigrams = 0;
  for (int i = 0; i < password.length - 1; i++) {
    String p = password[i] + password[i + 1];
    if (p == '00' || p == '11' || p == '22' || p == '33' || p == '44' ||
        p == '55' || p == '66' || p == '77' || p == '88' || p == '99') {
      bigrams++;
    }
  }

  if (bigrams > 2) {
    return 'Medium';
  }

  for (int i = 0; i < password.length - 3; i++) {
    String a = password[i], b = password[i + 1], c = password[i + 2],
        d = password[i + 3];
    if ((a.codeUnitAt(0) - b.codeUnitAt(0)).abs() == 1 &&
