        (c.codeUnitAt(0) - d.codeUnitAt(0)).abs() == 1) {
      return 'Medium';
    }
  }

  for (int i = 0; i < password.length - 4; i++) {
    String a = password[i], b = password[i + 1], c = password[i + 2],
