  if (n == 0) return "No readings";

  List<int> dp = List<int>.filled(n + 1, 0);
  List<int> parent = List<int>.filled(n + 1, -1);
  int maxLen = 0;
  int bestEnd = 0;

  for (int i = 1; i <= n; i++) {
    dp[i] = 1;
    parent[i] = i - 1;

    for (int j = 0; j < i - 1; j++) {
      if (schedule[i - 1] >= schedule[j] && dp[j] + 1 > dp[i]) {
        dp[i] = dp[j] + 1;
        parent[i] = j;
      }
    }

    if (dp[i] > maxLen) {
      maxLen = dp[i];
      bestEnd = i;
    }
  }

  if (maxLen == 1) {
    return "Best run: 1 day";
  }

  List<int> bestDays = [];
  int current = bestEnd;
  for (int j = maxLen - 1; j >= 0; j--) {
    bestDays.add(schedule[current - 1]);
    current = parent[current];
  }
  bestDays = bestDays.reversed.toList();

  String daysText = bestDays.join(' ');
  return "Best run: $maxLen days ($daysText)";
}

