int _levenshtein(String a, String b) {
  final int m = a.length;
  final int n = b.length;
  final List<List<int>> dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));
  for (int i = 0; i <= m; i++) dp[i][0] = i;
  for (int j = 0; j <= n; j++) dp[0][j] = j;
  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      final int cost = a[i - 1] == b[j - 1] ? 0 : 1;
      dp[i][j] = [dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost].reduce((int p, int q) => p < q ? p : q);
    }
  }
  return dp[m][n];
}

String _rotateRow(String row, int index) {
  int shift = index % row.length;
  if (shift == 0) return row;
  final StringBuffer result = StringBuffer();
  for (int i = 0; i < row.length; i++) {
    final int originalIndex = (i - shift) % row.length;
    if (originalIndex < 0) originalIndex += row.length;
    result.write(row[originalIndex]);
  }
  return result.toString();
}

