  int lastMaintenance = schedule[0];
  for (int i = 1; i < schedule.length; i++) {
    int nextLevel = schedule[i];
    int gap = nextLevel - currentLevel;
    if (gap > maxGap) return false;
    currentLevel = nextLevel;
  }
  int finalGap = schedule[0] - lastMaintenance;
  if (finalGap > maxGap) return false;
  return true;
}

