  final int maxValue = (1 << (maxCount * base)) - 1;

  final List<int> dp = List.filled(maxValue + 1, 0);
  dp[0] = 1;

  for (int mask = 1; mask <= maxValue; mask++) {
    for (int count = 1; count <= maxCount; count++) {
      if ((mask & (1 << (count * base))) != 0) {
        final int prev = mask ^ (1 << (count * base));
        dp[mask] += dp[prev];
      }
    }
  }

  print('Number of bitsets with $n bits: $dp[maxValue]');
}

