void fn0(List<String> args) {

  final List<String> items = args.isNotEmpty ? args : ['A', 'B', 'C'];

  final int n = items.length;
  const int maxDepth = 16;
  const int maxItems = 16;

  if (n > maxItems) {
    print('List too long for simple binary tree visualization. '
          'Use smaller lists for demonstration.');
    return;
  }

  if (n == 0) {
    print('Empty tree');
    return;
  }

  final List<List<String>> levels = [];
  int levelCount = 1;
  while (levelCount <= n) {
    levels.add(List<String>.filled(levelCount, ''));
    levelCount *= 2;
  }

  for (int i = 0; i < n; i++) {
    final int level = (i + 1).bitLength - 1;
    levels[level][i] = items[i];
  }

  final int treeHeight = levels.length;
  const int padding = 3;
  const int treeWidth = 80;
  const int rootX = treeWidth ~/ 2;
  const int rootLevel = 0;
  const int rootIndex = 0;

  final int maxLabelLength = levels.last.where((s) => s.isNotEmpty).reduce((a, b) => a.length > b.length ? a : b);
  const int nodeWidth = 6;
  const int labelWidth = 10;
  const int leftGap = 2;
  const int rightGap = 2;
  const int nodeGap = 4;
  const int indent = 2;

  final List<int> positions = List<int>.filled(n, 0);

  void buildPositions(int level, int index, int x) {
    positions[index] = x;

    if (level < treeHeight - 1) {
      final int left = 2 * index + 1;
      final int right = 2 * index + 2;

      if (left < n) {
        buildPositions(level + 1, left, x - nodeWidth - nodeGap);
      }
      if (right < n) {
        buildPositions(level + 1, right, x + nodeWidth + nodeGap);
      }
    }
  }

  buildPositions(rootLevel, rootIndex, rootX);

  for (int level = 0; level < treeHeight; level++) {
    int totalWidth = (level + 1) * nodeWidth + level * nodeGap;
    if (level > 0) totalWidth += (level - 1) * indent;

    int start = (treeWidth - totalWidth) ~/ 2;

    final List<String> line = List<String>.filled(treeWidth, ' ');
    int pos = start;

    for (int i = 0; i < levels[level].length; i++) {
      if (levels[level][i].isNotEmpty) {
        final int center = positions[i] + labelWidth ~/ 2;
        final int halfLen = maxLabelLength ~/ 2;
        final int left = center - halfLen;
        final int right = center + halfLen;

        for (int j = left; j <= right; j++) {
          if (j >= 0 && j < treeWidth) {
            line[j] = levels[level][i];
          }
        }

        if (level > 0) {
          int parentPos = positions[i] + labelWidth ~/ 2;
          int childPos = (level > 1) ? positions[i] : rootX;

          final int lineStart = parentPos - 2;
          final int lineEnd = (level > 1) ? parentPos + 1 : parentPos + 3;

          for (int j = lineStart; j <= lineEnd; j++) {
            if (j >= 0 && j < treeWidth) {
              line[j] = levels[level][i] == '' ? '-' : '|';
            }
          }
        }
      }
      pos += nodeWidth + nodeGap;
    }
    print(line.join());
  }

  for (int i = 0; i < n; i++) {
    print('Node "${items[i]}": level ${levels.where((s) => s.isNotEmpty && s.contains(items[i])).firstIndex}, '
          'position ${positions[i]}');
  }
}

