      buckets[bucket]++;
    }
  }
  return {
    'valid': symbols.length - buckets.fold(0, (a, b) => a + b),
    'invalid': buckets.fold(0, (a, b) => a + b),
    'validPerBucket': buckets.fold(0, (a, b) => a + b) > 0 ? buckets.reduce((a, b) => a > b ? a : b) : 0,
