List<int> dbscan(List<List<double>> data, double eps, int minPts) {
  int n = data.length;
  List<int> labels = List.filled(n, 0); 

  int clusterId = 0;

  for (int i = 0; i < n; i++) {

    if (labels[i] != 0) continue; 

    List<int> neighbors = regionQuery(data, i, eps);

    if (neighbors.length < minPts) {
      labels[i] = -1; 
      continue;
    }

    clusterId++;
    labels[i] = clusterId;

    expandCluster(data, labels, i, neighbors, clusterId, eps, minPts);
  }

  return labels;
}

void expandCluster(
  List<List<double>> data,
  List<int> labels,
  int pointIdx,
  List<int> neighbors,
  int clusterId,
  double eps,
  int minPts,
) {

  labels[pointIdx] = clusterId;

  int coreCount = neighbors.length;

  int index = 0;
  while (index < neighbors.length) {

    int current = neighbors[index];

    if (labels[current] == -1) {
      labels[current] = clusterId; 
    }
    if (labels[current] == 0) {
      labels[current] = clusterId; 
      coreCount++;
    }

    index++;
  }

  if (coreCount >= minPts) {

    for (int i = 0; i < data.length; i++) {
      if (labels[i] == 0) {
        double distance = euclideanDistance(data[i], data[pointIdx]);
        if (distance <= eps) {
          neighbors = regionQuery(data, i, eps);
          if (neighbors.length >= minPts) {
            for (int neighbor in neighbors) {
              if (!neighbors.contains(neighbor)) {
                neighbors.add(neighbor);
              }
            }
          }
        }
      }
    }
  }
}

List<int> regionQuery(List<List<double>> data, int pointIdx, double eps) {
  List<int> neighbors = [];
  for (int i = 0; i < data.length; i++) {
    double distance = euclideanDistance(data[pointIdx], data[i]);
    if (distance <= eps) {
      neighbors.add(i);
    }
  }
  return neighbors;
}

double euclideanDistance(List<double> p1, List<double> p2) {
  double sum = 0.0;
  for (int i = 0; i < p1.length; i++) {
    sum += (p1[i] - p2[i]) * (p1[i] - p2[i]);
  }
  return sum.sqrt();
}

