List<String> fn0(List<List<int>> grid) {
  List<String> result = [];
  int rows = grid.length;
  if (rows == 0) return result;
  int cols = grid[0].length;
  if (cols == 0) return result;

  List<List<bool>> visited = List.generate(
    rows,
    (_) => List<bool>.filled(cols, false),
  );

  List<int> dr = [0, 1, 0, -1];
  List<int> dc = [1, 0, -1, 0];

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        int count = 0;
        List<List<int>> queue = [[r, c]];
        visited[r][c] = true;
        while (queue.isNotEmpty) {
          List<int> curr = queue.removeAt(0);
          int nr = curr[0];
          int nc = curr[1];
          count++;
          for (int i = 0; i < 4; i++) {
            int nr2 = nr + dr[i];
            int nc2 = nc + dc[i];
            if (nr2 >= 0 &&
                nr2 < rows &&
                nc2 >= 0 &&
                nc2 < cols &&
                !visited[nr2][nc2]) {
              visited[nr2][nc2] = true;
              queue.add([nr2, nc2]);
            }
          }
        }
        int sum = 0;
        for (int r2 = 0; r2 < rows; r2++) {
          for (int c2 = 0; c2 < cols; c2++) {
            if (visited[r2][c2]) {
              sum += grid[r2][c2];
            }
          }
        }
        result.add('Region $count: sum=$sum');
      }
    }
  }
  return result;
}

