void fn0() {

  const int n = 8;

  List<List<int>> queens = List.generate(n, (_) => -1);

  bool isSafe(int row, int col) {
    for (int i = 0; i < row; i++) {
      int qCol = queens[i];
      if (qCol == col || 
          (i - row).abs() == (qCol - col).abs()) {
        return false;
      }
