void fn0() {

  const int INF = 1 << 60;

  int n = 6;
  List<List<int>> dist = [
    [0, 7, INF, 3, INF, 1],
    [INF, 0, 4, INF, INF, 2],
    [INF, INF, 0, INF, 6, INF],
    [INF, 5, INF, 0, INF, 7],
    [4, INF, INF, INF, 0, INF],
    [INF, INF, INF, INF, 2, 0],
  ];

  List<List<int>> dist2 = List.generate(n, (i) => List<int>.from(dist[i]));

  List<List<int>> path = List.generate(n, (i) => List<int>.from(List.filled(n, -1)));

  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (dist2[i][j] > dist2[i][k] + dist2[k][j]) {
          dist2[i][j] = dist2[i][k] + dist2[k][j];
          path[i][j] = k;
        }
      }
    }
  }

  print('Shortest distances between all pairs:');
  for (int i = 0; i < n; i++) {
    String row = '';
    for (int j = 0; j < n; j++) {
      row += dist2[i][j] == INF ? 'INF' : dist2[i][j].toString();
      if (j < n - 1) row += ' ';
    }
    print(row);
  }

  print('\nPath reconstruction:');
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (i != j) {
        List<int> p = [];
        int current = i;
        while (current != -1 && current != j) {
          p.add(current);
          current = path[current][j];
        }
        if (current == j) {
          p.add(j);
          print('Path from $i to $j: ${p.join(' -> ')}');
        } else {
          print('Path from $i to $j: No path exists');
        }
      }
    }
  }
}

