@pragma('vm:entry-point')
String fn0(List<int> startMasks, int days) {
  if (startMasks.isEmpty) return '';
  int n = startMasks.length;
  List<int> state = List<int>.filled(n, 0);
  for (int i = 0; i < n; i++) {
    state[i] = startMasks[i] & 1;
  }
  String getStateStr() {
    return state.map((v) => v == 1 ? 'W' : 'C').join('-');
  }
  Map<String, int> seen = {};
  int cycleStart = -1;
  int cycleLen = 0;
  for (int d = 0; d <= days; d++) {
    String key = getStateStr();
    int count = seen.putIfAbsent(key, () => 0) ?? 0;
    if (count == 0) {
      cycleStart = d;
    } else if (count == 1) {
      cycleLen = d - cycleStart;
    }
    if (count == 2) break;
    int nextState = 0;
    for (int i = 0; i < n; i++) {
      int countNeighbors = 0;
      for (int j = 0; j < n; j++) {
        if (state[j] == 1 && ((1 << i) & (1 << j)) != 0) {
          countNeighbors++;
        }
      }
      if (countNeighbors >= 2) {
        nextState |= 1 << i;
      }
    }
    state = List<int>.from(nextState.toBits());
  }
  if (cycleStart >= 0 && cycleLen > 0) {
    int remainder = (days - cycleStart) % cycleLen;
    days = cycleStart + remainder;
  }
  if (days >= 0) {
    String stateStr = getStateStr();
    return 'Day $days: $stateStr';
  } else {
    return 'Day $days: <empty>';
  }
}

