    for (int i = 0; i < code.length; i++) {
      if (code[i] == '.') {
        hasDot = true;
        break;
      }
    }
    if (!hasDot) continue;
    int sum = 0;
    for (int i = 0; i < idPart.length; i++) {
      sum += idPart.codeUnitAt(i);
    }
    if (sum % 3 == 0) {
      total++;
    }
  }
  return total;
}

