void fn0() {

  List<int> weights = [2, 3, 4, 5];
  List<int> values  = [3, 4, 5, 6];
  int capacity = 5;

  int n = weights.length;

  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (weights[i - 1] <= w) {

        dp[i][w] = 
          values[i - 1] + dp[i - 1][w - weights[i - 1]] > 
          dp[i - 1][w] ? 
          values[i - 1] + dp[i - 1][w - weights[i - 1]] : 
          dp[i - 1][w];
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  print('Maximum value: ${dp[n][capacity]}');

  int remainingWeight = capacity;
  List<bool> included = List.filled(n, false);

  for (int i = n; i > 0; i--) {
    if (dp[i][remainingWeight] != dp[i - 1][remainingWeight]) {
      included[i - 1] = true;
      remainingWeight -= weights[i - 1];
    }
  }

  print('Items included:');
  for (int i = 0; i < n; i++) {
    if (included[i]) {
      print('  Item ${i + 1}: weight = ${weights[i]}, value = ${values[i]}');
    }
  }
}

