List<int> fn0(String encoded, int startDayIndex, int numDays) {
  if (encoded.isEmpty) return [];
  List<int> days = [];
  int i = 0;
  int totalDays = 0;
  while (i < encoded.length) {
    int type = encoded.codeUnitAt(i) - 48;
    i++;
    int count = 0;
    bool hasDigit = false;
    while (i < encoded.length) {
      int digit = encoded.codeUnitAt(i) - 48;
      count = count * 10 + digit;
      hasDigit = true;
      i++;
    }
    if (!hasDigit) count = 1;
    for (int j = 0; j < count; j++) {
      if (type == 1) {
        days.add(30);
      } else if (type == 2) {
        days.add(15);
      } else if (type == 3) {
        days.add(7);
      } else if (type == 4) {
        days.add(3);
      } else {
        days.add(1);
      }
    }
    totalDays += count;
  }
  int endDayIndex = startDayIndex + numDays;
  if (endDayIndex > totalDays) {
    endDayIndex = totalDays;
  }
  int firstWindowStart = startDayIndex;
  int firstWindowEnd = startDayIndex + numDays - 1;
  int lastWindowStart = endDayIndex - numDays + 1;
  int lastWindowEnd = endDayIndex;
  int current = 0;
  int longest = 0;
  int longestStart = 0;
  int longestEnd = 0;
  int firstLongestStart = -1;
  int lastLongestStart = -1;
  for (int k = 0; k < days.length; k++) {
    current += days[k];
    if (k >= firstWindowStart && k <= firstWindowEnd) {
      if (current > longest) {
        longest = current;
        longestStart = firstWindowStart;
        longestEnd = firstWindowEnd;
        firstLongestStart = firstWindowStart;
      }
    }
    if (k >= lastWindowStart && k <= lastWindowEnd) {
      if (current > longest) {
        longest = current;
        longestStart = lastWindowStart;
        longestEnd = lastWindowEnd;
        lastLongestStart = lastWindowStart;
      }
    }
  }
  return [firstLongestStart, longestStart, longestEnd, lastLongestStart, longestStart, longestEnd];
}

