void fn0() {

  const int MAX_X = 8;
  const int MAX_Y = 8;

  List<List<int>> queens = List.generate(8, (row) => [row, 0]);

  bool isSafe(List<List<int>> queens, int newRow, int newY) {
    for (int i = 0; i < queens.length; i++) {
      int row1 = queens[i][0];
      int col1 = queens[i][1];

      if (col1 == newY) return false; 

      int rowDiff = (row1 - newRow).abs();
      int colDiff = (col1 - newY).abs();
      if (rowDiff == colDiff) return false; 
    }
    return true;
  }

  bool solveNQueens(List<List<int>> queens, int row) {
    if (row == MAX_X) {
      return true; 
    }

    for (int col = 0; col < MAX_Y; col++) {
      if (isSafe(queens, row, col)) {
        queens[row] = [row, col];

        if (solveNQueens(queens, row + 1)) {
          return true;
        }
      }
    }
    return false; 
  }

  if (solveNQueens(queens, 0)) {
    print('N-Queens solution found:');
    for (var queen in queens) {
      String rowStr = List.generate(MAX_Y, (c) => c == queen[1] ? 'Q' : '.').join();
      print(rowStr);
    }
  } else {
    print('No solution exists for N=8');
  }
}

