    print("Shortest distance from vertex $source to vertex $destination: ${dist[destination]}");
    if (dist[destination] != 1000000) {
      print("Path: $source -> ${getPath(prev, source, destination)} -> $destination");
    } else {
      print("Path: No path exists");
    }
  }
}

List<int> getPath(List<int> prev, int source, int destination) {
  final List<int> path = <int>[];
  int current = destination;
  while (current != -1 && current != source) {
    path.insert(0, current);
    current = prev[current];
  }
  if (current == -1) {
    return [];
  }
  path.insert(0, current);
  return path;
}

