    [2, 4],
    [3, 5],
    [4, 6],
  ];

  double eps = 2.0; 
  int minPts = 2;   

  List<int> labels = dbscan(points, eps, minPts);

  for (int i = 0; i < labels.length; i++) {
    print('Point ${points[i]} -> Cluster ${labels[i]}');
  }
