List<int> dbscan(List<List<double>> points, double eps, int minPts) {
  int n = points.length;
  List<int> labels = List.filled(n, 0); 
  int clusterId = 0;

  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) continue; 

    List<int> neighbors = regionQuery(points, i, eps);

    if (neighbors.length < minPts) {
      labels[i] = -1; 
    } else {
      clusterId++;
      expandCluster(points, labels, i, neighbors, clusterId, eps, minPts);
    }
  }

  return labels;
}

List<int> regionQuery(List<List<double>> points, int idx, double eps) {
  List<int> neighbors = [];
  for (int i = 0; i < points.length; i++) {
    double dist = euclideanDistance(points[idx], points[i]);
    if (dist <= eps) {
      neighbors.add(i);
    }
  }
  return neighbors;
}

void expandCluster(
    List<List<double>> points,
    List<int> labels,
    int pointIdx,
    List<int> neighbors,
    int clusterId,
    double eps,
    int minPts) {

  labels[pointIdx] = clusterId;

  List<int> seeds = List.from(neighbors);

  int seedsIdx = 0;
  while (seedsIdx < seeds.length) {
    int current = seeds[seedsIdx];

    if (labels[current] == -1) {
      labels[current] = clusterId; 
    }

    if (labels[current] == 0) {
      labels[current] = clusterId;
      List<int> currentNeighbors = regionQuery(points, current, eps);

      if (currentNeighbors.length >= minPts) {
        for (int nb in currentNeighbors) {
          if (!seeds.contains(nb)) {
            seeds.add(nb);
          }
        }
      }
    }

    seedsIdx++;
  }
}

double euclideanDistance(List<double> p1, List<double> p2) {
  double sum = 0;
  for (int i = 0; i < p1.length; i++) {
    sum += pow(p1[i] - p2[i], 2);
  }
  return sqrt(sum);
}

