  print('Original array: $arr');

  int getMax(List<int> list) {
    var maxVal = list[0];
    for (var i = 1; i < list.length; i++) {
      if (list[i] > maxVal) maxVal = list[i];
    }
    return maxVal;
  }

  void countingSort(List<int> list, int exp) {
    final int n = list.length;
    final output = List<int>.filled(n, 0);
    final count = List<int>.filled(10, 0);

    for (var i = 0; i < n; i++) {
      final digit = (list[i] ~/ exp) % 10;
      count[digit]++;
    }

    for (var i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    for (var i = n - 1; i >= 0; i--) {
      final digit = (list[i] ~/ exp) % 10;
      output[count[digit] - 1] = list[i];
      count[digit]--;
    }

    for (var i = 0; i < n; i++) {
      list[i] = output[i];
    }
  }

  for (var exp = 1, maxVal = getMax(arr); maxVal ~/ exp > 0; exp *= 10) {
    countingSort(arr, exp);
  }

  print('Sorted array: $arr');
}

