@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int popSize = 20;
  const int chromLength = 16;
  const int maxGenerations = 100;
  const double mutationRate = 0.01;
  const double crossoverRate = 0.7;

  List<List<int>> population = [];
  for (int i = 0; i < popSize; i++) {
    List<int> chrom = List.generate(chromLength, (_) => Random().nextBool() ? 1 : 0);
    population.add(chrom);
  }

  int fitness(List<int> chrom) {
    return chrom.fold(0, (sum, bit) => sum + bit);
  }

  List<int> tournamentSelect(List<List<int>> pop) {
    List<List<int>> tournament = List.generate(3, (_) => pop[Random().nextInt(pop.length)]);
    tournament.sort((a, b) => fitness(b) - fitness(a));
    return List.from(tournament[0]);
  }

  List<int> crossover(List<int> p1, List<int> p2) {
    if (Random().nextDouble() > crossoverRate) {
      return List.from(p1);
    }
    int point = Random().nextInt(chromLength);
    List<int> child = List.generate(point, (_) => p1[0]);
    for (int i = point; i < chromLength; i++) {
      child.add(p2[i]);
    }
    return child;
  }

  List<int> mutate(List<int> chrom) {
    for (int i = 0; i < chrom.length; i++) {
      if (Random().nextDouble() < mutationRate) {
        chrom[i] = 1 - chrom[i];
      }
    }
    return chrom;
  }

  int bestFit = -1;
  List<int>? bestChrom;
  List<int> bestFitnesses = [];
  List<int> bestChroms = [];

  for (int gen = 0; gen < maxGenerations; gen++) {
    List<List<int>> newPop = [];

    while (newPop.length < popSize) {
      List<int> parent1 = tournamentSelect(pop);
      List<int> parent2 = tournamentSelect(pop);
      List<int> child = crossover(parent1, parent2);
      child = mutate(child);
      newPop.add(child);
    }

    pop = newPop;
    int fit = fitness(pop[0]);
    bestChrom = fit > bestFit ? [List.from(pop[0])] : bestChrom;
    bestFit = fit > bestFit ? fit : bestFit;
    bestFitnesses.add(bestFit);
    bestChroms.add(bestChrom == null ? -1 : fitness(bestChrom!));

    print('Generation $gen: Best Fitness = $bestFit, Best Chrom = ${bestChrom?.join()}');
    if (bestFit == chromLength) {
      print('Solution found! Stopping early.');
      break;
    }
  }

  print('\nBest Chromosome: ${bestChrom?.join()}');
  print('Best Fitness: $bestFit');
  print('Generation History:');
  for (int i = 0; i < bestFitnesses.length; i++) {
    print('Gen ${i}: ${bestFitnesses[i]}');
  }
}

