@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int populationSize = 20;
  const int chromosomeLength = 16;
  const int generations = 50;
  const double crossoverRate = 0.7;
  const double mutationRate = 0.01;
  const int target = 0xFFFF; 

  final Random rand = Random(0);

  List<int> createChromosome() {
    return List<int>.generate(chromosomeLength, (_) => rand.nextBool() ? 1 : 0);
  }

  int chromosomeToInt(List<int> chr) {
    int value = 0;
    for (int i = 0; i < chr.length; i++) {
      value = value << 1 | chr[i];
    }
    return value;
  }

  int fitness(List<int> chr) {
    return chromosomeToInt(chr) ^ target;
  }

  List<int> tournamentSelection(List<List<int>> population, List<int> fitnesses) {
    List<int> indices = List<int>.generate(population.length, (i) => i);
    indices.shuffle(rand);

    List<int> selected = [];
    for (int i = 0; i < 2; i++) {
      selected.add(indices[i]);
    }

    int bestFit = fitness(population[selected[0]]);
    int bestIdx = selected[0];
    if (fitness(population[selected[1]]) < bestFit) {
      bestFit = fitness(population[selected[1]]);
      bestIdx = selected[1];
    }
    return population[bestIdx];
  }

  List<int> crossover(List<int> parent1, List<int> parent2) {
    if (rand.nextDouble() > crossoverRate) {
      return rand.nextBool() ? parent1 : parent2;
    }

    int point = rand.nextInt(chromosomeLength - 1) + 1;
    List<int> child = <int>[];
    child.addAll(parent1.take(point));
    child.addAll(parent2.skip(point));

    return child;
  }

  void mutate(List<int> chr) {
    for (int i = 0; i < chr.length; i++) {
      if (rand.nextDouble() < mutationRate) {
        chr[i] = 1 - chr[i];
      }
    }
  }

  List<List<int>> population = List<List<int>>.generate(
    populationSize, 
    (_) => createChromosome()
  );

  int bestFit = -1;
  int bestValue = -1;

  for (int generation = 0; generation < generations; generation++) {

    List<int> fitnesses = List<int>.generate(
      population.length, 
      (i) => fitness(population[i])
    );

    List<List<int>> newPopulation = [];

    while (newPopulation.length < populationSize) {

      List<int> parent1 = tournamentSelection(population, fitnesses);
      List<int> parent2 = tournamentSelection(population, fitnesses);

      List<int> child = crossover(parent1, parent2);
      mutate(child);

      newPopulation.add(child);

      int childFit = fitness(child);
      if (childFit < bestFit || (childFit == bestFit && (chromosomeToInt(child) > bestValue))) {
        bestFit = childFit;
        bestValue = chromosomeToInt(child);
      }
    }

    population = newPopulation;

    if (bestFit == 0) {
      print('Solution found at generation $generation!');
      print('Chromosome: ${population.first.map((b) => b == 1 ? '1' : '0').join()}');
      print('Binary:      ${bestValue.toRadixString(2).padLeft(chromosomeLength, '0')}');
      print('Decimal:     $bestValue');
      break;
    }

    if (generation % 10 == 0) {
      print('Generation $generation:');
      print('  Best fitness: $bestFit');
      print('  Best value:   ${bestValue.toRadixString(2).padLeft(chromosomeLength, '0')} ($bestValue)');
    }
  }

  if (bestFit != 0) {
    print('\nSearch completed.');
    print('Best found: ${bestValue.toRadixString(2).padLeft(chromosomeLength, '0')} ($bestValue)');
    print('Target:     ${target.toRadixString(2).padLeft(chromosomeLength, '0')} ($target)');
  }
}

