  for (int i = n ~/ 2 - 1; i >= 0; i--) {
    heapify(arr, n, i);
  }

  for (int i = n - 1; i > 0; i--) {

    int temp = arr[0];
    arr[0] = arr[i];
    arr[i] = temp;

    heapify(arr, i, 0);
  }

  print('Sorted array: $arr');

  List<int> arr2 = [12, 11, 13, 5, 6, 7];
  print('\nOriginal array 2: $arr2');

  int m = arr2.length;
  for (int j = m ~/ 2 - 1; j >= 0; j--) {
    heapify(arr2, m, j);
  }

  for (int j = m - 1; j > 0; j--) {
    int temp = arr2[0];
    arr2[0] = arr2[j];
    arr2[j] = temp;

    heapify(arr2, j, 0);
  }

  print('Sorted array 2: $arr2');
}

void heapify(List<int> arr, int n, int i) {

  int largest = i;
  int left = 2 * i + 1;
  int right = 2 * i + 2;

  if (left < n && arr[left] > arr[largest]) {
    largest = left;
  }

  if (right < n && arr[right] > arr[largest]) {
    largest = right;
  }

  if (largest != i) {
    int swapTemp = arr[i];
    arr[i] = arr[largest];
    arr[largest] = swapTemp;

    heapify(arr, n, largest);
  }
}

