class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';
}

class Interval {
  final double lo;
  final double hi;

  Interval(this.lo, this.hi);

  double length() => hi - lo;

  @override
  String toString() => '[$lo, $hi]';
}

class Segment {
  final Point p1;
  final Point p2;
  final Interval xSpan;
  final Interval ySpan;

  Segment(this.p1, this.p2)
      : xSpan = Interval(min(p1.x, p2.x), max(p1.x, p2.x)),
        ySpan = Interval(min(p1.y, p2.y), max(p1.y, p2.y)),
        p1 = p1,
        p2 = p2;

  bool contains(Point point) =>
      point.x >= xSpan.lo &&
      point.x <= xSpan.hi &&
      point.y >= ySpan.lo &&
      point.y <= ySpan.hi;

  double distanceTo(Point point) =>
      sqrt(pow(p1.x - point.x, 2) + pow(p1.y - point.y, 2));

  double distanceBetween(Segment other) {
    if (contains(other.p1) || contains(other.p2)) {
      return 0.0;
    }

    final double x1 = p1.x;
    final double y1 = p1.y;
    final double x2 = p2.x;
    final double y2 = p2.y;
    final double x3 = other.p1.x;
    final double y3 = other.p1.y;
    final double x4 = other.p2.x;
    final double y4 = other.p2.y;

    final double denominator =
        (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);

    if (denominator.abs() < 1e-10) {
      return min(distanceTo(other.p1), distanceTo(other.p2));
    }

    final double tNumerator = (x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3);
    final double uNumerator = (x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3);

    final double t = tNumerator / denominator;
    final double u = uNumerator / denominator;

    if (t >= 0.0 && t <= 1.0 && u >= 0.0 && u <= 1.0) {
      final double x = x1 + t * (x2 - x1);
      final double y = y1 + t * (y2 - y1);
      return sqrt(pow(x - x3, 2) + pow(y - y3, 2));
    }

    double minDist = double.infinity;
    for (final point in [p1, p2, other.p1, other.p2]) {
      final double d = other.distanceTo(point);
      if (d < minDist) minDist = d;
    }

    return minDist;
  }

  @override
  String toString() => 'Segment(${p1} -> ${p2})';
}

class RSegment {
  final Segment segment;
  RSegment? left;
  RSegment? right;
  double xSpanLo = double.infinity;
  double xSpanHi = -double.infinity;

  RSegment(this.segment);

  void build(int depth, int maxDepth) {
    if (depth >= maxDepth || !left!.hasChildren()) {
      return;
    }

    final double midX = (xSpanLo + xSpanHi) / 2;
    left = RSegment(segment);
    right = RSegment(segment);

    for (final point in [segment.p1, segment.p2]) {
      if (point.x < midX) {
        left!.segment = Segment(point, segment.p1);
      } else {
        right!.segment = Segment(point, segment.p2);
      }
    }

    left!.xSpanLo = segment.xSpan.lo;
    left!.xSpanHi = segment.xSpan.hi;
    right!.xSpanLo = segment.xSpan.lo;
    right!.xSpanHi = segment.xSpan.hi;

    left!.build(depth + 1, maxDepth);
    right!.build(depth + 1, maxDepth);
  }

  bool hasChildren() => left != null && right != null;
}

