List<String> fn0(List<int> packetSizes, int maxGap) {
  List<String> zones = [];
  if (packetSizes.isEmpty) {
    zones.add('idle:0');
    return zones;
  }
  int n = packetSizes.length;
  List<int> dp = List.filled(n, 0);
  dp[0] = 1;
  for (int i = 1; i < n; i++) {
    if (packetSizes[i] - packetSizes[i - 1] <= maxGap) {
      dp[i] = dp[i - 1] + 1;
    } else {
      dp[i] = 1;
    }
  }
  int maxLen = dp.reduce((a, b) => a > b ? a : b);
  int start = 0;
  for (int i = 0; i < n; i++) {
    if (dp[i] == maxLen) {
      start = i - maxLen + 1;
      break;
    }
  }
  String best = 'idle:$maxLen';
  for (int i = 0; i < maxLen; i++) {
    if (packetSizes[start + i] > packetSizes[start]) {
      best = 'data:$maxLen';
      break;
    }
  }
  zones.add(best);
  return zones;
}

