  int n = dailyUnits.length;
  int low = 0, high = n;
  while (low < high) {
    int mid = (low + high + 1) ~/ 2;
    int sum = 0;
    for (int i = 0; i < mid; i++) {
      int u = dailyUnits[i];
      if (u < 0) u = 0;
      if (u > 100) u = 100;
      sum += u;
    }
    if (sum >= maintenanceUnits) low = mid;
    else high = mid - 1;
  }
  int chargeDay = -1;
  int chargeValue = 0;
  for (int i = 0; i < dailyUnits.length; i++) {
    int u = dailyUnits[i];
    if (u < 0) u = 0;
    if (u > 100) u = 100;
    if (u == maxCharge) {
      chargeDay = i;
      chargeValue = u;
      break;
    }
  }
  return [low, chargeValue];
}

