int fn0(List<List<int>> grid, int threshold) {
  if (grid.isEmpty || grid[0].isEmpty || threshold < 0) {
    return 0;
  }

  final int rows = grid.length;
  final int cols = grid[0].length;
  final List<List<int>> dp = List.generate(
    rows,
    (_) => List.filled(cols, 0),
  );

  int maxSum = grid[0][0] >= threshold ? grid[0][0] : 0;
  dp[0][0] = grid[0][0] >= threshold ? grid[0][0] : 0;

  for (int c = 1; c < cols; c++) {
    final int val = grid[0][c];
    final int prev = dp[0][c - 1];
    final int curr = val >= threshold ? val + prev : prev;
    dp[0][c] = curr;
    if (curr > maxSum) {
      maxSum = curr;
    }
  }

  for (int r = 1; r < rows; r++) {
    final int val = grid[r][0];
    final int prev = dp[r - 1][0];
    final int curr = val >= threshold ? val + prev : prev;
    dp[r][0] = curr;
    if (curr > maxSum) {
      maxSum = curr;
    }
  }

  for (int r = 1; r < rows; r++) {
    for (int c = 1; c < cols; c++) {
      final int val = grid[r][c];
      final int option1 = val >= threshold
          ? val + dp[r - 1][c]
          : dp[r - 1][c];
      final int option2 = val >= threshold
          ? val + dp[r][c - 1]
          : dp[r][c - 1];
      final int option3 = val >= threshold
          ? val + dp[r - 1][c - 1]
          : 0;
      dp[r][c] = option1 > option2 ? (option1 > option3 ? option1 : option3)
          : (option2 > option3 ? option2 : option3);
      if (dp[r][c] > maxSum) {
        maxSum = dp[r][c];
      }
    }
  }

  return maxSum;
}

