  void quickSort(List<int> arr, int low, int high) {
    if (low < high) {

      final int partition = _partition(arr, low, high);

      quickSort(arr, low, partition - 1);
      quickSort(arr, partition + 1, high);
    }
  }

  int _partition(List<int> arr, int low, int high) {
