    int i = low - 1; 

    for (int j = low; j < high; j++) {
      if (arr[j] <= pivot) {
        i++;
        final int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
    }

    final int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;
    return i + 1;
  }

  print('Original array: $arr');
  quickSort(arr, 0, arr.length - 1);
  print('Sorted array: $arr');
}

