void fn0() {

  final int vertexCount = 9;
  final List<List<int>> edges = [
    [0, 1],
    [0, 2],
    [1, 2],
    [1, 3],
    [1, 4],
    [2, 3],
    [2, 4],
    [3, 4],
    [5, 6],
    [5, 7],
    [6, 7],
    [6, 8],
    [7, 8],
  ];

  List<int> parent = List.filled(vertexCount, -1);
  List<int> rank = List.filled(vertexCount, 0);

  int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]]; 
      x = parent[x];
    }
    return x;
  }

  bool union(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);
    if (rootX == rootY) {
      return false; 
    }
    if (rank[rootX] < rank[rootY]) {
      parent[rootX] = rootY;
    } else if (rank[rootX] > rank[rootY]) {
      parent[rootY] = rootX;
    } else {
      parent[rootY] = rootX;
      rank[rootX]++;
    }
    return true;
  }

  for (int i = 0; i < vertexCount; i++) {
    parent[i] = i;
  }

  for (var edge in edges) {
    int u = edge[0];
    int v = edge[1];
    if (!union(u, v)) {
      print('Edge [$u, $v] forms a cycle!');
    }
  }

  print('Final parent array: $parent');
  print('Final rank array: $rank');
}

