  print('Original array: $arr');

  int getMax(List<int> list) {
    int maxVal = list[0];
    for (int i = 1; i < list.length; i++) {
      if (list[i] > maxVal) {
        maxVal = list[i];
      }
    }
    return maxVal;
  }

  void countingSort(List<int> list, int exp) {
    int n = list.length;
    List<int> output = List<int>.filled(n, 0);
    List<int> count = List<int>.filled(10, 0);

    for (int i = 0; i < n; i++) {
      int digit = (list[i] ~/ exp) % 10;
      count[digit]++;
    }

    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    for (int i = n - 1; i >= 0; i--) {
      int digit = (list[i] ~/ exp) % 10;
      output[count[digit] - 1] = list[i];
      count[digit]--;
    }

    for (int i = 0; i < n; i++) {
      list[i] = output[i];
    }
  }

  void radixSort(List<int> list) {
    int maxVal = getMax(list);
    int exp = 1;

    while (maxVal ~/ exp > 0) {
      countingSort(list, exp);
      exp *= 10;
    }
  }

  radixSort(arr);
  print('Sorted array: $arr');

  List<int> testArray = [170, 45, 75, 90, 802, 24, 2, 66];
