Set<int> fn0(List<int> requests, int windowSize, int maxIdle) {
  final Set<int> served = <int>{};
  final List<int> queue = <int>[];
  int servedCount = 0;
  int lastServed = -1;
  int head = 0;

  for (int i = 0; i < requests.length; i++) {
    int req = requests[i];
    while (head <= i && requests[head] == req) {
      queue.add(requests[head]);
      head++;
    }
    if (head > i) continue;
    if (queue.isEmpty) continue;
    if (servedCount < maxIdle) {
      served.add(req);
      queue.remove(req);
      servedCount++;
    } else {
      bool canServe = false;
      int left = 0;
      int right = queue.length - 1;
      while (left <= right) {
        int mid = (left + right) ~/ 2;
        if (queue[mid] < lastServed + windowSize) {
          canServe = true;
          break;
        }
        if (queue[mid] < lastServed) {
          right = mid - 1;
        } else {
          left = mid + 1;
        }
      }
      if (canServe) {
        served.add(req);
        queue.remove(req);
        lastServed = req;
      }
    }
  }
  return served;
}

