Map<String, int> fn0(List<int> pixels, int tolerance) {
  if (pixels.isEmpty) {
    return {'red': 0, 'green': 0, 'blue': 0};
  }

  List<List<int>> rects = [];
  for (int i = 0; i < pixels.length; i += 4) {
    int r = pixels[i];
    int g = pixels[i + 1];
    int b = pixels[i + 2];
    int a = pixels[i + 3];

    if (a < 255) {
      continue;
    }

    int top = r > g ? (r > b ? r : b) : (g > b ? g : b);
    int bottom = r < g ? (r < b ? r : b) : (g < b ? g : b);

    rects.add([bottom, top]);
  }

  if (rects.isEmpty) {
    return {'red': 0, 'green': 0, 'blue': 0};
  }

  List<int> reds = [];
  List<int> greens = [];
  List<int> blues = [];

  for (var rect in rects) {
    int bottom = rect[0];
    int top = rect[1];

    int lo = bottom - tolerance;
    int hi = top + tolerance;

    if (lo < 0) {
      lo = 0;
    }

    if (hi > 255) {
      hi = 255;
    }

    if (lo <= hi) {
      reds.add(lo);
      reds.add(hi);
      greens.add(lo);
      greens.add(hi);
      blues.add(lo);
      blues.add(hi);
    }
  }

  reds.sort();
  greens.sort();
  blues.sort();

  int rArea = 0;
  for (int i = 1; i < reds.length; i += 2) {
    int w = reds[i] - reds[i - 1];
    rArea += w;
  }

  int gArea = 0;
  for (int i = 1; i < greens.length; i += 2) {
    int w = greens[i] - greens[i - 1];
    gArea += w;
  }

  int bArea = 0;
  for (int i = 1; i < blues.length; i += 2) {
    int w = blues[i] - blues[i - 1];
    bArea += w;
  }

  int total = rArea + gArea + bArea;
  return {
    'red': (rArea * 255 + total ~/ 2) ~/ total,
    'green': (gArea * 255 + total ~/ 2) ~/ total,
    'blue': (bArea * 255 + total ~/ 2) ~/ total,
  };
}

