  int rows = moistureGrid.length;
  int cols = moistureGrid[0].length;
  List<List<int>> dp = List.generate(
    rows + 1,
    (_) => List.filled(cols + 1, 0),
  );

  for (int i = 1; i <= rows; i++) {
    for (int j = 1; j <= cols; j++) {
      int currentMoisture = moistureGrid[i - 1][j - 1];
      int maxPrev = 0;
      if (i > 1) maxPrev = dp[i - 1][j];
      if (j > 1) if (dp[i][j - 1] > maxPrev) maxPrev = dp[i][j - 1];
      dp[i][j] = maxPrev + currentMoisture;
    }
  }

  int maxMoisture = dp[rows][cols];
  int low = 0, high = maxMoisture;
  while (low < high) {
    int mid = (low + high + 1) ~/ 2;
    bool possible = false;
    for (int r = 1; r <= rows; r++) {
      int left = 0, right = cols;
      while (left <= right) {
        int mid2 = (left + right) ~/ 2;
        int sum = 0;
        for (int c = mid2; c < cols; c++) {
          sum += moistureGrid[r - 1][c];
          if (sum >= mid) break;
        }
        if (sum >= mid) {
          possible = true;
          break;
        }
        if (sum < mid) {
          left = mid2 + 1;
        } else {
          right = mid2 - 1;
        }
      }
    }
    if (possible) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }

