Iterable<List<int>> combinations(int n, int k) sync* {

  if (k < 0 || k > n) {
    return;
  }

  if (k == 0) {
    yield <int>[];
    return;
  }

  if (k == 1) {
    for (var i = 1; i <= n; i++) {
      yield [i];
    }
    return;
  }

  var combinations = <List<int>>[];
  var current = List<int>.generate(k, (i) => i + 1);

  while (true) {

    combinations.add(List<int>.from(current));

    int i = k - 1;
    while (i >= 0 && current[i] == n - k + i + 1) {
      i--;
    }

    if (i < 0) {
      break;
    }

    current[i]++;

    for (int j = i + 1; j < k; j++) {
      current[j] = current[j - 1] + j - i;
    }
  }

  for (var c in combinations) {
    yield c;
  }
}

