      if (i - coin >= 0) {
        dp[i] = dp[i] < dp[i - coin] + 1 ? dp[i] : dp[i - coin] + 1;
      }
    }
  }

  if (dp[amount] > amount) {
    print('No solution: Cannot make amount $amount with the given coins.');
  } else {
    print('Minimum coins needed to make amount $amount: ${dp[amount]}');
  }
}

