  List<int> depth = List.filled(n, 0);
  List<int> heavy = List.filled(n, -1);
  List<int> head = List.filled(n, 0);
  List<int> pos = List.filled(n, 0);
  List<int> size = List.filled(n, 0);
  List<int> heavySize = List.filled(n, 0);

  void dfs(int v, int p, int d) {
    parent[v] = p;
    depth[v] = d;
    size[v] = 1;

    int maxSubtree = 0;
    for (int u in data[v].toSet()) {
      if (u != p) {
        dfs(u, v, d + 1);
        size[v] += size[u];

        if (size[u] > maxSubtree) {
          maxSubtree = size[u];
          heavy[v] = u;
        }
      }
    }
  }

  int curPos = 0;
  void hld(int v, int h) {
    head[v] = h;
    pos[v] = curPos++;
    heavySize[h] += size[v];

    if (heavy[v] != -1) {
      hld(heavy[v], h);
    }

    for (int u in data[v].toSet()) {
      if (u != parent[v] && u != heavy[v]) {
        hld(u, u);
      }
    }
  }

  dfs(0, -1, 0);
  hld(0, 0);

  print('Node | Parent | Depth | Heavy | Head | Position | Heavy Size');
  for (int i = 0; i < n; i++) {
    int h = head[i];
