@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final items = [
    Item('item1', 10),
    Item('item2', 20),
    Item('item3', 30),
    Item('item4', 40),
    Item('item5', 50),
  ];

  final capacity = 50;

  final n = items.length;

  var dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  for (var i = 1; i <= n; i++) {
    for (var w = 0; w <= capacity; w++) {

      if (items[i - 1].weight > w) {
        dp[i][w] = dp[i - 1][w];
      } else {

        dp[i][w] = 
          dp[i - 1][w] > (dp[i - 1][w - items[i - 1].weight] + items[i - 1].value)
            ? dp[i - 1][w]
            : dp[i - 1][w - items[i - 1].weight] + items[i - 1].value;
      }
    }
  }

  var w = capacity;
  var selectedItems = <String>[];
  for (var i = n; i > 0 && w > 0; i--) {
    if (dp[i][w] != dp[i - 1][w]) {
      selectedItems.add(items[i - 1].name);
      w -= items[i - 1].weight;
    }
  }

  print('Knapsack problem with capacity = $capacity');
  print('Items:');
  for (var item in items) {
    print('  ${item.name}: value = ${item.value}, weight = ${item.weight}');
  }

  print('\nMaximum value achievable: ${dp[n][capacity]}');
  print('Selected items:');
  for (var name in selectedItems) {
    print('  $name');
  }
}

