@pragma('vm:entry-point')
void fn0() {

  final List<int> weights = [2, 3, 4, 5];
  final List<int> values  = [3, 4, 5, 6];
  final int capacity      = 5;

  final int n = weights.length;

  final List<List<int>> dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {

      if (weights[i - 1] > w) {

        dp[i][w] = dp[i - 1][w];
      } else {

        dp[i][w] = dp[i - 1][w].clamp(0, dp[i - 1][w - weights[i - 1]] + values[i - 1]);
      }
    }
  }

  int maxVal = dp[n][capacity];

  print('Knapsack problem with:');
  print('Weights  = $weights');
  print('Values   = $values');
  print('Capacity = $capacity');
  print('\nMaximum value achievable: $maxVal');

  List<int> items = [];
  int weightSum = 0;
  int valueSum  = 0;

  int w = capacity;
  for (int i = n; i > 0 && valueSum < maxVal; i--) {
    if (dp[i][w] != dp[i - 1][w]) {
      items.add(i - 1);
      weightSum += weights[i - 1];
      valueSum  += values[i - 1];
      w -= weights[i - 1];
    }
  }

  print('\nChosen items (0-based index): $items');
  print('Total weight: $weightSum');
  print('Total value:  $valueSum');
}

