        isBetter = true;
      } else if (first.length == bestFirst.length) {
        if (first.compareTo(bestFirst) < 0) {
          isBetter = true;
        } else if (first == bestFirst) {
          if (code.length < best.length) {
            isBetter = true;
          } else if (code.length == best.length &&
              code.compareTo(best) < 0) {
            isBetter = true;
          }
        }
      }
    }

    if (isBetter) {
      bestSum = sum;
      best = code;
      bestFirst = first;
    }
  }

  return best;
}

