class Point {
  final double x, y;

  const Point(this.x, this.y);

  double distanceTo(Point other) {
    return math.sqrt((x - other.x).abs().pow(2) + (y - other.y).abs().pow(2));
  }

  double distanceToTheOrigin() {
    return distanceTo(const Point(0.0, 0.0));
  }

  @override
  String toString() => 'Point($x, $y)';
}

class Rectangle {
  final Point topLeft;
  final Point bottomRight;

  const Rectangle(this.topLeft, this.bottomRight);

  bool contains(Point point) {
    return point.x >= topLeft.x &&
        point.x <= bottomRight.x &&
        point.y >= bottomRight.y &&
        point.y <= topLeft.y;
  }

  double area() {
    return (bottomRight.x - topLeft.x) * (topLeft.y - bottomRight.y);
  }

  @override
  String toString() {
    return 'Rectangle($topLeft, $bottomRight)';
  }
}

