bool nextPermutation(List<int> arr) {
  var n = arr.length;
  var i = n - 2;
  while (i >= 0 && arr[i] >= arr[i + 1]) {
    i--;
  }
  if (i < 0) return false; 

  var j = n - 1;
  while (arr[i] >= arr[j]) {
    j--;
  }
  var tmp = arr[i];
  arr[i] = arr[j];
  arr[j] = tmp;

  var right = n - 1;
  var left = i + 1;
  while (left < right) {
    tmp = arr[left];
    arr[left] = arr[right];
    arr[right] = tmp;
    left++;
    right--;
  }
  return true;
}

void cyclicPermutation(List<int> arr) {
  var n = arr.length;
  if (n == 0) return;
  var last = arr.last;
  for (var i = n - 1; i > 0; i--) {
    arr[i] = arr[i - 1];
  }
  arr[0] = last;
}

