  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      int dx = (points[i][0] - points[j][0]).abs();
      int dy = (points[i][1] - points[j][1]).abs();
      dist[i][j] = dx + dy; 
    }
  }

  List<bool> isVisited = List.filled(n, false);

  int minDist = 999999;
  List<int> bestPath = [];
  int bestTourCost = 999999;

  void permute(int index, List<int> path) {
    if (index == n) {
      int cost = 0;
      for (int i = 0; i < n; i++) {
        cost += dist[path[i]][path[(i + 1) % n]]; 
      }
      if (cost < bestTourCost) {
        bestTourCost = cost;
        bestPath = List.from(path);
      }
      return;
    }

    for (int i = 0; i < n; i++) {
      if (!isVisited[i]) {
        path.add(i);
        isVisited[i] = true;
        permute(index + 1, path);
        path.removeLast();
        isVisited[i] = false;
      }
    }
  }

  permute(0, []);

  print('Best path (order of visiting points):');
