List<String> fn0(List<String> commands) {
  List<String> stack = [];
  List<String> history = [];
  for (String cmd in commands) {
    if (cmd.startsWith('PUSH ')) {
      stack.add(cmd.substring(5));
      history.add('PUSH ${cmd.substring(5)}');
    } else if (cmd == 'POP' && stack.isNotEmpty) {
      String popped = stack.removeLast();
      history.add('POP $popped');
    } else if (cmd == 'UNDO') {
      if (history.isNotEmpty) {
        String last = history.removeLast();
        if (last.startsWith('PUSH ')) {
          stack.removeLast();
        } else if (last == 'POP') {
          if (stack.isNotEmpty) stack.add(history.removeLast());
        }
      }
    }
  }
  return stack;
}

