List<int> fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return [];

  int rows = grid.length;
  int cols = grid[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  List<int> spiralSizes = [];
  void spiralSearch(int r, int c, int maxVal, int size) {
    if (size > 1) {
      spiralSizes.add(size);
    }
    List<List<int>> dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    int d = 0;
    while (true) {
      int nr = r + dirs[d][0];
      int nc = c + dirs[d][1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc] && grid[nr][nc] == maxVal) {
        visited[nr][nc] = true;
        spiralSearch(nr, nc, maxVal, size + 1);
        r = nr;
        c = nc;
      } else {
        int nextD = (d + 1) % 4;
        if (nextD == 0) {
          int endR = r + dirs[d][0];
          int endC = c + dirs[d][1];
          if (endR >= 0 && endR < rows && endC >= 0 && endC < cols && grid[endR][endC] == maxVal) {
            spiralSearch(endR, endC, maxVal, 2);
          }
          break;
        } else {
          d = nextD;
        }
      }
    }
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        spiralSearch(r, c, grid[r][c], 1);
      }
    }
  }

  spiralSizes.sort();
  return spiralSizes;
}

