bool fn0(List<int> readings, int target, int startDay, int endDay) {
  if (target < 0 || startDay < 0 || endDay < startDay || endDay < 0) {
    return false;
  }

  if (readings.isEmpty) {
    return (startDay == 0 || startDay > 0) && endDay == 0;
  }

  int n = readings.length;
  List<int> dp = List.filled(n + 1, 0);
  dp[0] = (startDay == 0 || startDay > 0) ? 1 : 0;

  for (int i = 1; i <= n; i++) {
    int curr = readings[i - 1];
    int prev = 0;
    int lo = 0, hi = i - 1;
    while (lo <= hi) {
      int mid = lo + (hi - lo) ~/ 2;
      if (dp[mid] > 0) {
        prev = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }

    if (prev == 0 && startDay > 0) {
      dp[i] = 0;
    } else if (prev == 0) {
      dp[i] = 1;
    } else {
      dp[i] = dp[prev];
    }

    int daysSincePrev = (i - prev - 1) % 7;
    int adjusted = (curr + daysSincePrev) % 100;
    int remaining = (target - adjusted) % 100;
    remaining = remaining < 0 ? remaining + 100 : remaining;

    int reachLo = i - remaining;
    int reachHi = i - 1;
    if (reachLo < 0) reachLo = 0;
    if (reachHi > prev) reachHi = prev;

    if (reachLo <= reachHi) {
      int best = 0;
      lo = reachLo;
      hi = reachHi;
      while (lo <= hi) {
        int mid = lo + (hi - lo) ~/ 2;
        if (dp[mid] > 0) {
          best = mid;
          lo = mid + 1;
        } else {
          hi = mid - 1;
        }
      }
      if (best > 0) {
        int daysSinceBest = (i - best - 1) % 7;
        int adjustedBest = (curr + daysSinceBest) % 100;
        int required = (target - adjustedBest) % 100;
        required = required < 0 ? required + 100 : required;
        if (required == 0) {
          dp[i] = dp[i] > 1 ? dp[i] : 2;
        }
      }
    }
  }

  int lo = startDay;
  int hi = n;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (dp[mid] > 0) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return hi == endDay;
}

