import 'dart:async';
import 'dart:convert';
import 'dart:collection';

class TrieNode {
  Map<String, TrieNode> children = {};
  bool isWord = false;
  String? word;
  int depth = 0;
}

class Trie {
  TrieNode root = TrieNode();

  void add(String word) {
    TrieNode node = root;
    for (int i = 0; i < word.length; i++) {
      String ch = word[i];
      node.depth = i;
      if (!node.children.containsKey(ch)) {
        node.children[ch] = TrieNode();
      }
      node = node.children[ch]!;
    }
    node.isWord = true;
    node.word = word;
  }

  void search(String pattern, int maxDepth, List<String> results) {
    _searchRecursive(root, "", pattern, 0, maxDepth, results);
  }

  void _searchRecursive(
      TrieNode node, String current, String pattern, int depth,
      int maxDepth, List<String> results) {
    if (depth > maxDepth) return;
    if (pattern.isEmpty) {
      if (node.isWord) {
        results.add(current);
      }
      return;
    }

    String first = pattern[0].toLowerCase();
    if (node.children.containsKey(first)) {
      _searchRecursive(node.children[first]!, current + first, pattern.substring(1), depth, maxDepth, results);
    }

    if (pattern.length >= 2) {
      String second = pattern[1].toLowerCase();
      if (node.children.containsKey(second)) {
        results.add(current + pattern[0].toUpperCase() + second);
      }
    }
  }
}

