@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<int>> board = List.generate(9, (_) => List.filled(9, 0));

  List<List<List<int>>> solutions = [];

  bool isSafe(List<List<int>> board, int row, int col, int k) {
    for (int i = 0; i < row; i++) {
      if (board[i][col] == k) return false;
    }

    for (int i = 0; i < col; i++) {
      if (board[row][i] == k) return false;
    }

    int i = row - 1;
    int j = col - 1;
    while (i >= 0 && j >= 0) {
      if (board[i][j] == k) return false;
      i--;
      j--;
    }

    i = row - 1;
    j = col + 1;
    while (i >= 0 && j < 9) {
      if (board[i][j] == k) return false;
      i--;
      j++;
    }

    return true;
  }

  void solveNQueens(List<List<int>> board, int row, int n, List<List<int>> currentSolution) {
    if (row == n) {

      List<int> queenPositions = List.generate(n, (i) => board[i].indexOf(1));
      currentSolution.add(queenPositions);
      return;
    }

    for (int col = 0; col < n; col++) {

      if (isSafe(board, row, col, 1)) {
        board[row][col] = 1;
        currentSolution.add([row, col]);
        solveNQueens(board, row + 1, n, currentSolution);
        currentSolution.removeLast();
        board[row][col] = 0;
      }
    }
  }

  int n = 9; 
  solveNQueens(board, 0, n, solutions);

  print('Solutions for $n-Queens on a 9x9 board:');
  for (int i = 0; i < solutions.length && i < 10; i++) {
    print('Solution ${i + 1}: ${solutions[i]}');
  }

  print('\nTotal solutions found: ${solutions.length}');
}

