@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final int vertices = 5;
  final List<List<int>> edges = [
    [0, 1],
    [0, 2],
    [1, 2],
    [1, 3],
    [2, 3],
    [3, 4],
  ];

  List<int>? find(int x, List<int> parent) {
    if (parent[x] != x) {
      parent[x] = find(parent[x], parent)!;
    }
    return parent[x];
  }

  void union(int x, int y, List<int> parent, List<int> rank) {
    final int xr = find(x, parent)!;
    final int yr = find(y, parent)!;
    if (xr == yr) return;

    if (rank[xr] < rank[yr]) {
      parent[xr] = yr;
    } else if (rank[xr] > rank[yr]) {
      parent[yr] = xr;
    } else {
      parent[yr] = xr;
      rank[xr]++;
    }
  }

  void makeSet(List<int> parent, List<int> rank) {
    for (int i = 0; i < vertices; i++) {
      parent.add(i);
      rank.add(0);
    }
  }

  List<int> parent = [];
  List<int> rank = [];
  makeSet(parent, rank);

  for (final edge in edges) {
    final int u = edge[0];
    final int v = edge[1];
    union(u, v, parent, rank);
  }

  final int root = find(0, parent)!;
  bool allConnected = true;
  for (int i = 1; i < vertices; i++) {
    if (find(i, parent) != root) {
      allConnected = false;
      break;
    }
  }

  print('All vertices connected: $allConnected');
}

