class Point {
  final num x, y;
  const Point(this.x, this.y);
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<Point> points = [
    Point(2, 3),
    Point(12, 30),
    Point(40, 50),
    Point(5, 1),
    Point(12, 10),
    Point(3, 4)
  ];

  num minDistance = 999999;
  List<Point> minPair = [];

  void bruteForce(List<Point> pts) {
    for (int i = 0; i < pts.length; i++) {
      for (int j = i + 1; j < pts.length; j++) {
        num dist = ((pts[i].x - pts[j].x) ^ 2 + (pts[i].y - pts[j].y) ^ 2);
        if (dist < minDistance) {
          minDistance = dist;
          minPair = [pts[i], pts[j]];
        }
      }
    }
  }

  List<Point> strip(List<Point> pts, num d) {
    List<Point> stripPts = [];
    for (var p in pts) {
      if ((p.x - minPair[0].x).abs() < d) {
        stripPts.add(p);
      }
    }
    stripPts.sort((a, b) => (a.y - b.y).compareTo(0));
    return stripPts;
  }

  num dist(Point p1, Point p2) => ((p1.x - p2.x) ^ 2 + (p1.y - p2.y) ^ 2);

  num closestPair(List<Point> pts) {
    int n = pts.length;
    if (n <= 3) {
      bruteForce(pts);
      return minDistance;
    }

    int mid = n ~/ 2;
    Point midPoint = pts[mid];

    List<Point> leftPts = pts.sublist(0, mid);
    List<Point> rightPts = pts.sublist(mid);

    num dl = closestPair(leftPts);
    num dr = closestPair(rightPts);

    num d = min(dl, dr);

    stripPts = strip(pts, d);

    for (int i = 0; i < stripPts.length; i++) {
      for (int j = i + 1; j < stripPts.length && (stripPts[j].y - stripPts[i].y).abs() < d; j++) {
        num dist = dist(stripPts[i], stripPts[j]);
        if (dist < d) {
          d = dist;
          minPair = [stripPts[i], stripPts[j]];
        }
      }
    }

    return d;
  }

  List<Point> sortedPts = List.from(points);
  sortedPts.sort((a, b) => (a.x - b.x).compareTo(0));

  num minDist = closestPair(sortedPts);
  print('Minimum distance: ${minDist.sqrt()}');
  print('Between points: ${minPair[0]} and ${minPair[1]}');
}

