void fn0(List<String> args) {

  List<String> numbers = args.isNotEmpty ? args : ['3', '14', '5', '1', '9', '2', '6', '4', '8', '7'];

  int n = numbers.length;
  if (n == 0) {
    print('List is empty');
    return;
  }

  List<String> arr = numbers.map((s) => int.parse(s)).toList();

  int minVal = arr.reduce((a, b) => a < b ? a : b);
  int maxVal = arr.reduce((a, b) => a > b ? a : b);
  int range = maxVal - minVal + 1;

  List<int> count = List.filled(range, 0);

  for (int i = 0; i < n; i++) {
    count[arr[i] - minVal]++;
  }

  for (int i = 1; i < range; i++) {
    count[i] += count[i - 1];
  }

  List<int> output = List.filled(n, 0);

  for (int i = n - 1; i >= 0; i--) {
    int element = arr[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  for (int i = 0; i < n; i++) {
    arr[i] = output[i] + minVal;
  }

  print('Sorted list: $arr');
}

