void fn0(List<String> args) {

  List<int> values = args.isNotEmpty
      ? args.map(int.parse).toList()
      : [60, 100, 120, 50];

  int capacity = args.length > values.length
      ? int.parse(args[values.length])
      : 10;

  int n = values.length;

  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (values[i - 1] > w) {
        dp[i][w] = dp[i - 1][w];
      } else {
        dp[i][w] = dp[i - 1][w] > dp[i - 1][w - values[i - 1]] + values[i - 1]
            ? dp[i - 1][w]
            : dp[i - 1][w - values[i - 1]] + values[i - 1];
      }
    }
  }

  print('Maximum value achieved: ${dp[n][capacity]}');
}

