/// Simulates a particle moving in a 2D grid with random walks and walls.
/// Particles bounce off walls, avoid each other, and have limited lifespans.
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int width  = 50;
  const int height = 20;

  const double maxAge    = 100;
  const double speed     = 1.0;
  const double bounceFactor = 0.8;

  double randomRange(double min, double max) => min + (max - min) * Random().nextDouble();

  class Particle {
    double x = randomRange(0, width);
    double y = randomRange(0, height);
    double vx = randomRange(-speed, speed);
    double vy = randomRange(-speed, speed);
    double age = 0;

    void update() {
      age++;

      x += vx;
      y += vy;

      if (x <= 0) {
        x = 0;
        vx = -vx * bounceFactor;
      } else if (x >= width) {
        x = width;
        vx = -vx * bounceFactor;
      }

      if (y <= 0) {
        y = 0;
        vy = -vy * bounceFactor;
      } else if (y >= height) {
        y = height;
        vy = -vy * bounceFactor;
      }

      if (age > maxAge) {
        vx = randomRange(-speed, speed);
        vy = randomRange(-speed, speed);
        age = 0;
      }
    }

    void draw() {
      print('P($x, $y) v($vx, $vy) a:$age');
    }
  }

  List<Particle> particles = [];
  int numParticles = 50;

  for (int i = 0; i < numParticles; i++) {
    particles.add(Particle());
  }

  for (int frame = 0; frame < 200; frame++) {
    print('--- Frame $frame ---');

    for (Particle p in particles) {
      p.update();
      p.draw();
    }

    print('--- End Frame $frame ---');

    if (frame % 10 == 0 && particles.length > 10) {
      particles.removeAt(Random().nextInt(particles.length));
    }
  }
}

