  final int vertices = 5;
  final List<List<int>> adjacency = List.generate(
    vertices,
    (_) => <int>[],
  );
  final List<int> degrees = List.filled(vertices, 0);

  void addEdge(int u, int v) {
    adjacency[u].add(v);
    adjacency[v].add(u);
    degrees[u]++;
    degrees[v]++;
  }

  addEdge(0, 1);
  addEdge(0, 2);
  addEdge(0, 3);
  addEdge(1, 2);
  addEdge(1, 4);

  final List<int> currentColor = List.filled(vertices, -1);
  final int colors = 3;

  bool isSafe(int v, int c) {
    for (var neighbor in adjacency[v]) {
      if (currentColor[neighbor] == c) return false;
    }
    return true;
  }

  bool graphColoring(int v) {
    if (v == vertices) return true;
    for (int c = 0; c < colors; c++) {
      if (isSafe(v, c)) {
        currentColor[v] = c;
        if (graphColoring(v + 1)) return true;
        currentColor[v] = -1;
      }
    }
    return false;
  }

  if (graphColoring(0)) {
    print('Graph coloring successful with $colors colors:');
    for (int i = 0; i < vertices; i++) {
      print('Vertex $i -> Color ${currentColor[i]}');
    }
  } else {
    print('Graph cannot be colored with $colors colors.');
  }
}

