  int end = 9;

  for (int d = 1; d <= digitCount; d++) {
    int current = 9;
    if (d > 1) {
      current = 9 * (9 * (d - 1) + 1);
    }
    count += current;

    int tempStart = start;
    int tempEnd = end;

    start = tempEnd + 1;
    end = tempEnd + 1;

    for (int i = 0; i < d - 1; i++) {
      int newStart = tempEnd * 9 + 1;
      int newEnd = tempEnd * 9 + 9;
      start = newStart < start ? newStart : start;
      end = newEnd > end ? newEnd : end;
      tempStart = tempEnd;
      tempEnd = newEnd;
    }

    if (d == 1) {
      minDigit = 1;
      maxDigit = 9;
    } else {
      minDigit = tempStart;
      maxDigit = tempEnd;
    }

    int range = maxDigit - minDigit + 1;
    count += range;
  }

  return count;
}

