void fn0() {




  final data = [
    [1, 0, 0],
    [1, 1, 0],
    [1, 0, 1],
  ];

  final int n = data.length;
  final int k = data[0].length;

  final int totalPatterns = 1 << n;
  final int patternBits = n < 30 ? n : 30; 

  List<int> lfsr = [];
  for (int i = 0; i < n; i++) {
    lfsr.add(data[i].first == 1 ? 1 : 0);
  }

  final Set<int> visited = {};
  final List<int> output = [];

  int toInt(List<int> bits) {
    int val = 0;
    for (int i = 0; i < bits.length; i++) {
      val = val * 2 + bits[i];
    }
    return val;
  }

  int popcount(int x) {
    int count = 0;
    while (x != 0) {
      count += x & 1;
      x >>= 1;
    }
    return count;
  }

  while (true) {

    final int currentState = toInt(lfsr);
    if (visited.contains(currentState)) break;
    visited.add(currentState);

    final int nextBit = (lfsr[n - 1] ^ popcount(toInt(lfsr))) & 1;
    final int nextState = toInt(lfsr.sublist(1)..add(nextBit));

    output.add(nextState);

    if (output.length == totalPatterns) break;
  }

  for (final int pattern in output) {
    for (int i = 0; i < n; i++) {
      final bit = (pattern >> i) & 1;
      print(bit == 1 ? '#' : '.', separator: '');
    }
    print('');
  }
}

