void fn0() {

  List<int> nums = [10, 9, 2, 5, 3, 7, 101, 18];

  int longestIncreasingSubsequence(List<int> nums) {
    if (nums.isEmpty) return 0;

    List<int> tails = List.filled(nums.length + 1, 0);
    int len = 1;
    tails[0] = nums[0];

    for (int i = 1; i < nums.length; i++) {
      if (nums[i] < tails[0]) {
        tails[0] = nums[i];
      } else if (nums[i] > tails[len - 1]) {
        tails[len] = nums[i];
        len++;
      } else {
        int left = 0, right = len - 1;
        while (left < right) {
          int mid = (left + right) ~/ 2;
          if (tails[mid] < nums[i]) {
            left = mid + 1;
          } else {
            right = mid;
          }
        }
        tails[left] = nums[i];
      }
    }
    return len;
  }

  int lisLength = longestIncreasingSubsequence(nums);
  print('Length of Longest Increasing Subsequence: $lisLength');
}

